export const hasOwn = (obj, key) => Object.prototype.hasOwnProperty.call(obj, key)

// Keys inlined at build time. Overlay manifests can never replace them.
export const FIRST_PARTY_KEYS = Object.keys(STACKS)
// A key the extendsTarget fix text can name as an example.
export const EXTENDS_EXAMPLE = FIRST_PARTY_KEYS.find((k) => k !== 'other') || 'other'
export let STACK_KEYS = Object.keys(STACKS)
export let STACK_AGENT = Object.fromEntries(Object.entries(STACKS).map(([k, v]) => [k, v.agent]))
// Agent name -> { plugin, stacks, source }; rebuilt by installOverlay.
export let AGENT_INFO = buildAgentInfo({})
// Overlay key -> { source, plugin, trusted, sha256 }; empty until installOverlay runs.
export let OVERLAY_META = {}
// First-party key -> key of the trusted overlay that extends it; repos Detect classifies as the first-party key
// take the overlay key (see resolveRepo).
export let EXTENDS = {}
// Stack keys named by a manifest the run rejected -> why, and the sources of rejected manifests whose keys
// could not be read; see resolveRepo.
export let DECLINED_KEYS = {}
export let DECLINED_UNNAMED = []
// True when this run rejected, ignored or distrusted any manifest; see toolingFallbackAllowed.
export let MANIFESTS_DECLINED = false

export const NOT_RUN_UNTRUSTED = 'not run (untrusted manifest)'
export const NOT_RUN_DECLINED = 'not run (stack manifest not used'

// True for an overlay key whose manifest hash is not in the trust store. No command
// from such a manifest may run: every command accessor below returns empty for it.
export const isUntrustedStack = (stack) => hasOwn(OVERLAY_META, stack) && !OVERLAY_META[stack].trusted

// Command-bearing manifest blocks (traits, extras) as the workflows may use them: empty for an untrusted overlay.
export const traitsFor = (stack) => (hasOwn(STACK_TRAITS, stack) && !isUntrustedStack(stack) ? STACK_TRAITS[stack] : {})

// Space-joined debug-statement patterns for a stack, for the gate grep. A key
// without an entry, or an untrusted overlay key, uses the patterns of the catch-all `other` entry.
export function debugScanFor(stack) {
  const entry = hasOwn(STACKS, stack) && !isUntrustedStack(stack) ? STACKS[stack] : STACKS.other
  return entry.debugPatterns.join(' ')
}

// A repo is the frontend when its detected role says so or its stack's manifest does.
export function isFrontendRepo(r) {
  return r.role === 'frontend' || !!(hasOwn(STACKS, r.stack) && STACKS[r.stack].role === 'frontend')
}

// Stack-specific build-gate warning from the manifest, with {devUrl} filled in; '' when the stack has none.
export function buildGateGuardFor(repo, devUrl) {
  const text = repo && traitsFor(repo.stack).buildGateGuard
  if (!text) return ''
  return '\n- ' + text.split('{devUrl}').join(String(devUrl))
}

// The exec wrapper a repo's gates run through: the stack manifest declares it and Detect reported its marker
// file in the repo (or, for a manifest with workdir, in a directory above it). Null for an untrusted overlay,
// a stack without one or a repo without the marker.
// running: false means not running whether or not the manifest declares a running check: Detect omits running
// for a wrapper without one, so false comes only from applyExtends' default for an overlay with no facts.
// prefix is what a gate command is appended to: the command, plus the workdir flag and <root>/<dir> for a repo
// below the marker's directory. mapFrom is the container path of the repo, null without workdir.
// unplaced: true means the manifest declares workdir and Detect reported a dir that cleanRepoFields dropped
// (dirUnusable): the marker sits above the repo, and the bare command would run in the container's root,
// not in the repo, so its gates must not run. A wrapper with no dir reported runs at the root as before.
export function execWrapperFor(repo) {
  const declared = repo && traitsFor(repo.stack).execWrapper
  if (!declared || !repo.execWrapper || repo.execWrapper.present !== true) return null
  const workdir = declared.workdir
  const dir = repo.execWrapper.dir
  const nested = !!workdir && typeof dir === 'string' && dir !== '.'
  return {
    command: declared.command,
    notRunning: repo.execWrapper.running === false,
    unplaced: !!workdir && repo.execWrapper.dirUnusable === true,
    prefix: nested ? `${declared.command} ${workdir.flag} ${workdir.root}/${dir}` : declared.command,
    mapFrom: workdir ? (nested ? `${workdir.root}/${dir}` : workdir.root) : null,
    containerRoot: workdir ? workdir.root : null,
  }
}

// Whether c can continue a path: a letter, digit or one of . _ ~ - /.
export function isPathChar(c) {
  return c !== undefined && /[A-Za-z0-9._~/-]/.test(c)
}

/**
 * Rewrites container paths in a wrapped gate's output to repo-relative ones. The gate ran inside the
 * container, so the paths it prints do not exist on the host, and the fix loop opens them there. Only a path
 * token is rewritten: <mapFrom>/<x> becomes <x>, and for a repo below the container root, <root>/<x> becomes
 * ../<x> (one ../ per dir segment). The prefix itself, as echoed in a command line, and a bare root stay as
 * they are.
 * @param {string} text gate details
 * @param {{ command: string, prefix: string, mapFrom: string|null, containerRoot: string|null }} wrapper from execWrapperFor
 * @returns {string}
 * @example mapContainerPaths('FILE: /srv/app/cms/src/x.js, /srv/app/lib/y.js', { command: 'run', prefix: 'run --dir /srv/app/cms', mapFrom: '/srv/app/cms', containerRoot: '/srv/app' })
 * // 'FILE: src/x.js, ../lib/y.js'
 */
export function mapContainerPaths(text, wrapper) {
  if (!wrapper || !wrapper.mapFrom || typeof text !== 'string') return text
  const replaceTokens = (s, from, to) => {
    const head = `${from}/`
    let out = ''
    let i = 0
    for (let at = s.indexOf(head); at !== -1; at = s.indexOf(head, i)) {
      const startsToken = at === 0 || !isPathChar(s[at - 1])
      const hasRest = isPathChar(s[at + head.length])
      out += s.slice(i, at) + (startsToken && hasRest ? to : head)
      i = at + head.length
    }
    return out + s.slice(i)
  }
  const up = wrapper.mapFrom === wrapper.containerRoot ? '' : '../'.repeat(wrapper.mapFrom.slice(wrapper.containerRoot.length + 1).split('/').length)
  const mapPiece = (piece) => {
    const own = replaceTokens(piece, wrapper.mapFrom, '')
    return up ? replaceTokens(own, wrapper.containerRoot, up) : own
  }
  return wrapper.prefix === wrapper.command ? mapPiece(text) : text.split(wrapper.prefix).map(mapPiece).join(wrapper.prefix)
}

// The running check as Detect is told to run it: a command that must exit 0, or a command whose JSON output must carry a value.
export function runningCheckText(check) {
  if (typeof check === 'string') return `\`${check}\``
  return `\`${check.command}\` (passes when it exits 0 and a JSON line of its output has ${check.jsonField} equal to ${check.equals})`
}

/**
 * The skip text of a gate whose requires is unmet. A string names the missing file. A list names its unmet
 * entries when they are known, and the whole requirement when they are not.
 * @param {string|Array<string|string[]>} requires the gate's declared requires
 * @param {Array<string|string[]>} [missing] the unmet entries, as declared; entries the list does not declare are ignored
 * @returns {string}
 * @example requiresSkipText(['bin/tool', ['a.conf', 'b.conf'], 'src/app'], ['src/app']) // 'not run (requires src/app)'
 */
export function requiresSkipText(requires, missing) {
  if (typeof requires === 'string') return `not run (${requires.split('/').pop()} not installed)`
  const unmet = Array.isArray(missing) ? requires.filter((e) => missing.some((m) => sameRequiresEntry(e, m))) : []
  return `not run (requires ${(unmet.length ? unmet : requires).map((e) => (Array.isArray(e) ? `one of ${e.join(', ')}` : e)).join('; ')})`
}

// Whether two requires entries are the same: equal paths, or one-of lists holding the same paths in any order.
export function sameRequiresEntry(a, b) {
  if (typeof a === 'string' || typeof b === 'string') return a === b
  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false
  return a.every((p) => b.includes(p))
}

// The requirement as Detect reads it: "needs <path>", or "needs <a> and one of <b>, <c>" for the list form.
export function requiresDetectText(requires) {
  if (typeof requires === 'string') return `needs ${requires}`
  return `needs ${requires.map((e) => (Array.isArray(e) ? `one of ${e.join(', ')}` : e)).join(' and ')}`
}

// The devUrlFields of an execWrapper's running check; [] for a string check or none.
export function devUrlFieldsOf(wrapper) {
  const check = wrapper && wrapper.requiresRunning
  return check && typeof check === 'object' && Array.isArray(check.devUrlFields) ? check.devUrlFields : []
}

// Stack keys whose execWrapper declares workdir: their marker may sit in a directory above the repo.
export function workdirStacks() {
  return Object.keys(STACK_TRAITS).filter((k) => STACK_TRAITS[k].execWrapper && STACK_TRAITS[k].execWrapper.workdir)
}

// Detect prompt fragment asking for the exec-wrapper marker of every stack that declares one; '' when none does.
export function execWrapperDetectLine() {
  const rules = Object.keys(STACK_TRAITS).filter((k) => STACK_TRAITS[k].execWrapper).map((k) => {
    const w = STACK_TRAITS[k].execWrapper
    return `${k}: marker ${w.when}${w.requiresRunning ? `, running check ${runningCheckText(w.requiresRunning)}` : ''}`
  })
  if (!rules.length) return ''
  const hostRules = Object.keys(STACK_TRAITS).filter((k) => devUrlFieldsOf(STACK_TRAITS[k].execWrapper).length).map((k) => `${k}: ${devUrlFieldsOf(STACK_TRAITS[k].execWrapper).join(', ')}`)
  const hosts = hostRules.length
    ? ` For a manifest whose running check declares devUrlFields (${hostRules.join('; ')}; a discovered manifest names its own), when the check passes set reportedDevHosts to the hostname of every URL at those dotted paths of the same JSON output (a field holds a URL or a list of URLs; the hostname only, without scheme, port or path); omit reportedDevHosts otherwise.`
    : ''
  const line = ` EXEC WRAPPER — for a repo whose stack manifest declares execWrapper (${rules.join('; ')}; a discovered manifest names its own), set execWrapper {present} to whether the marker file exists in that repo and, when present and the manifest declares a running check, {running} to whether that check passes (run it in that repo); omit running for a wrapper without a running check.${hosts}`
  const nested = workdirStacks()
  if (!nested.length) return line
  return `${line} For a manifest whose execWrapper declares workdir (${nested.join(', ')}; a discovered manifest declares its own), the marker also counts as present when it is in an ancestor directory of the repo: check each ancestor, nearest first, up to the filesystem root, only with the Glob tool on the literal absolute path <ancestor>/<marker>, never reading the file, and set {dir} to the repo's path relative to the directory that holds the marker ("." when the marker is in the repo itself, plain relative path characters only); omit dir for any other wrapper.`
}

// The narrow exception to the outside-the-project rule that the workdir marker search needs; '' without workdir.
export function workdirOutsideRule() {
  return workdirStacks().length ? ' The one other check allowed outside the project is the EXEC WRAPPER ancestor marker search below: a Glob of that literal marker path, nothing else.' : ''
}

// Gates the greenfield scaffold installs: the stack's gates minus those it skips; none for an untrusted overlay.
export function scaffoldGatesFor(stack) {
  if (!hasOwn(STACKS, stack) || isUntrustedStack(stack)) return []
  const skip = traitsFor(stack).scaffoldSkipGates || []
  return STACKS[stack].gates.filter((g) => !skip.includes(g.name))
}

// Command that exports a backend's route list for contract-sync; '' when the stack has none or is untrusted.
export function routeListCommandFor(stack) {
  return traitsFor(stack).routeListCommand || ''
}

/**
 * The add-on that ships a stack: a first-party key through FIRST_PARTY_FILES, an overlay key through its source.
 * @param {string} stack Stack key.
 * @returns {{ dir: string|null, plugin: string|null, source: string|null }} dir: the add-on directory (file-copy
 *   installs stage its files under .claude/<kind>/<dir>/); plugin: the plugin name; source: the overlay's manifest source.
 */
export function addonFor(stack) {
  for (const [dir, keys] of Object.entries(FIRST_PARTY_FILES)) {
    if (keys.includes(stack)) return { dir, plugin: FIRST_PARTY_PLUGINS.find((p) => p === `sdd-kit-${dir}`) || null, source: null }
  }
  if (!hasOwn(OVERLAY_META, stack)) return { dir: null, plugin: null, source: null }
  const source = OVERLAY_META[stack].source
  const plugin = /^plugin:([^@]+)/.exec(source)
  return { dir: null, plugin: plugin ? plugin[1] : null, source }
}

/**
 * Where a backend stack's contract-sync template lives, from its manifest's contractSync.template (a path
 * relative to the add-on root). The add-on is named explicitly: a workflow agent gets no placeholder
 * substitution and runs from the core plugin, so it must look the add-on's install directory up itself.
 * @param {string} stack Stack key.
 * @returns {string} Prompt text naming every location, or '' when the stack declares no template or is untrusted.
 * @example contractTemplateFor('acme') // first-party add-on directory "acme", plugin "sdd-kit-acme"
 * // "templates/contract-sync in the sdd-kit-acme plugin's install directory (plugin mode: ...), or .claude/templates/acme/contract-sync in file-copy installs"
 */
export function contractTemplateFor(stack) {
  const template = traitsFor(stack).contractTemplate
  if (!template) return ''
  const { dir, plugin, source } = addonFor(stack)
  const locations = []
  if (plugin) locations.push(`${template} in the ${plugin} plugin's install directory (plugin mode: its installPath in \`claude plugin list --json\` or ~/.claude/plugins/installed_plugins.json, or its --plugin-dir path)`)
  if (dir) locations.push(`.claude/templates/${dir}/${template.replace(/^templates\//, '')} in file-copy installs`)
  if (!locations.length) locations.push(`${template} in the add-on that provides ${source || `the ${stack} stack`}`)
  return locations.join(', or ')
}

export function isContractConsumer(stack) {
  return !!(hasOwn(STACK_TRAITS, stack) && STACK_TRAITS[stack].contractConsumer)
}

// Extras whose fields carry commands (scaffold, ci, e2e, migrations, audit, packageManagers): empty for an untrusted overlay.
export const extrasFor = (stack) => (hasOwn(STACK_EXTRAS, stack) && !isUntrustedStack(stack) ? STACK_EXTRAS[stack] : {})

// Skill names the manifest lists for a stack: { conventions, testing, scaffold } (absent groups are empty).
// Empty for an untrusted overlay (OD-17a): its steps run as the default agent with no stack skills.
export function skillsFor(stack) {
  const s = (hasOwn(STACK_EXTRAS, stack) && !isUntrustedStack(stack) ? STACK_EXTRAS[stack] : {}).skills || {}
  return { conventions: s.conventions || [], testing: s.testing || [], scaffold: s.scaffold || [] }
}

// Every distinct skill name the manifest lists for a stack, conventions first.
export function skillNamesFor(stack) {
  const s = skillsFor(stack)
  return Array.from(new Set([...s.conventions, ...s.testing, ...s.scaffold]))
}

// Skills for a phase that only writes tests: the manifest's testing group, else its conventions group.
export function testSkillNamesFor(stack) {
  const s = skillsFor(stack)
  return s.testing.length ? s.testing : s.conventions
}

// Source directories the debug scan greps, as one prompt fragment; the repo's own source roots when the
// manifest names none or is untrusted (the directories are pasted into a command line).
export function sourceDirsFor(stack) {
  const dirs = extrasFor(stack).sourceDirs || []
  return dirs.length ? dirs.join(' ') : "the repo's source directories"
}

/**
 * Package managers a stack's manifest declares, in manifest order; the last entry is the default
 * (no lockfile). Empty when the stack declares none or is untrusted.
 * @param {string} stack Stack key.
 * @returns {{ name: string, lockfiles: string[], run: string, exec?: string }[]}
 */
export function packageManagersFor(stack) {
  return extrasFor(stack).packageManagers || []
}

// The package manager a repo uses: the one Detect recorded, else its stack's default; null when the stack declares none.
export function packageManagerFor(repo, fallbackToDefault) {
  const pms = packageManagersFor(repo.stack)
  const found = pms.find((p) => p.name === repo.packageManager)
  if (found) return found
  return fallbackToDefault === false ? null : pms[pms.length - 1] || null
}

// Fills <pm> and <pmx> in a manifest command; unchanged when there is no package manager.
export function fillPackageManager(command, pm) {
  return pm ? command.split('<pmx>').join(pm.exec || pm.run).split('<pm>').join(pm.run) : command
}

// Prompt sentence telling an agent how <pm>/<pmx> expand for a stack; '' when the stack declares no package managers.
export function packageManagerLine(stack) {
  const pms = packageManagersFor(stack)
  if (!pms.length) return ''
  return `Use the package manager the repo uses (its lockfile; default ${pms[pms.length - 1].name}) for every command: <pm> is ${pms.map((p) => p.run).join(', ')}, and <pmx> is ${pms.map((p) => p.exec || p.run).join(', ')} respectively.`
}

// Scaffold block of the manifest ({ command, tooling[] }); empty when the stack declares none or is untrusted.
export function scaffoldFor(stack) {
  const sc = extrasFor(stack).scaffold || {}
  return { command: sc.command || '', tooling: sc.tooling || [] }
}

// CI block of the manifest ({ services[], setup[] }); empty when the stack declares none or is untrusted.
export function ciFor(stack) {
  const ci = extrasFor(stack).ci || {}
  return { services: ci.services || [], setup: ci.setup || [] }
}

// E2E block of the manifest ({ configGlob, file, run, convention, seed }); null when the stack declares none or is untrusted.
export function e2eFor(stack) {
  return extrasFor(stack).e2e || null
}

// What a backend stack adds to a frontend's E2E step ({ convention, seed }); null when it declares nothing or is untrusted.
export function e2eBackendFor(stack) {
  return extrasFor(stack).e2eBackend || null
}

// Regression test file for the E2E step from the manifest's e2e.file pattern ({slug} filled in); '' when the manifest names none.
export function e2eFileFor(stack, slug) {
  const e2e = e2eFor(stack)
  if (!e2e || !e2e.file) return ''
  return e2e.file.split('{slug}').join(slug || '<short-feature-slug>')
}

export const NO_E2E_DECLARED = 'not run (stack declares no e2e)'
export const NO_APP_URL = 'not run (no reachable app URL)'

// A skipped step reports status 'skip' with its reason. Skips are informational: they never change the recommendation.
export function skipResult(reason) {
  return { status: 'skip', ran: false, written: false, details: reason }
}

// Why the E2E step does not run for a frontend repo, as a skip result; null when it should run.
// `requested` is the explicit e2e argument (true, false or null), `configFound` whether a file matches the manifest's configGlob.
export function e2eSkipFor(frontend, requested, configFound) {
  if (requested === false) return skipResult('skipped — e2e:false')
  if (frontend && isUntrustedStack(frontend.stack)) return skipResult(NOT_RUN_UNTRUSTED)
  const e2e = frontend ? e2eFor(frontend.stack) : null
  if (!e2e) return skipResult(NO_E2E_DECLARED)
  if (requested === true || configFound) return null
  return skipResult(`skipped — no ${e2e.configGlob} in the repo (pass e2e:true to add one)`)
}

// Detect prompt fragment: which file proves a repo has e2e set up, per stack, from the manifests.
export function e2eGlobsLine() {
  const rows = STACK_KEYS.filter((k) => e2eFor(k)).map((k) => `${k}: ${e2eFor(k).configGlob}`)
  return rows.length ? `e2eConfig=true when the repo has a file matching its stack's e2e config glob (${rows.join('; ')})` : ''
}

// Browser URL: the url argument, else the frontend repo's devUrl, else any repo's devUrl, else ''.
// A repo's own devUrl (from Detect) wins over its manifest's default. Detect's value is used only when it
// passes isDevUrl, and a manifest's default only when the manifest is first-party or trusted. The url argument
// may also use a host reported by the repo it serves: the first frontend repo, else the first repo.
export function resolveDevUrl(hint, repos) {
  const list = repos || []
  const served = list.find((r) => isFrontendRepo(r)) || list[0]
  const given = runUrlHint(hint, served && served.reportedDevHosts)
  if (given) return given
  const front = list.find((r) => isFrontendRepo(r) && repoDevUrl(r))
  const any = front || list.find((r) => repoDevUrl(r))
  return any ? repoDevUrl(any) : ''
}

export let urlHintLogged = false

// The run-level url argument when it passes isDevUrl for the hosts of the repo it serves; otherwise null, with
// one log line per run.
export function runUrlHint(hint, repoHosts) {
  if (!hint) return null
  if (isDevUrl(hint, repoHosts)) return hint
  if (!urlHintLogged) {
    urlHintLogged = true
    log(`url argument is not a local dev URL — ignored. Fix: pass an http(s) URL on ${DEV_URL_HOST_TEXT}`)
  }
  return null
}

// A repo's own dev URL: Detect's value when it passes isDevUrl with the repo's reported hosts, else its
// first-party or trusted manifest's default when that passes too. An approved manifest is still text the user
// wrote, so its devUrl is never trusted to point the browser phases at a host outside the dev-URL rule.
export function repoDevUrl(r) {
  const manifestUrl = (hasOwn(STACKS, r.stack) && !isUntrustedStack(r.stack) && !r.declinedStack && STACKS[r.stack].devUrl) || ''
  const hosts = r.reportedDevHosts
  return (isDevUrl(r.devUrl, hosts) ? r.devUrl : '') || (isDevUrl(manifestUrl, hosts) ? manifestUrl : '')
}

/**
 * args.repos in either accepted form as one list of { path, role?, url? }: an array of such entries (or of
 * plain paths), or the older { backend, frontend } object of paths. More than one backend is an error.
 * @param {unknown} hints args.repos
 * @returns {{ entries: { path: string, role?: string, url?: string }[], error: string }}
 * @example normalizeRepoHints({ backend: '../api', frontend: '../web' }).entries // [{ path: '../api', role: 'backend' }, { path: '../web', role: 'frontend' }]
 */
export function normalizeRepoHints(hints) {
  let entries = []
  if (Array.isArray(hints)) {
    entries = hints.map((h) => (typeof h === 'string' ? { path: h } : h)).filter((h) => h && typeof h === 'object' && typeof h.path === 'string')
  } else if (hints && typeof hints === 'object') {
    entries = Object.keys(hints).filter((k) => typeof hints[k] === 'string').map((k) => ({ path: hints[k], role: k }))
  }
  const backends = entries.filter((e) => e.role === 'backend')
  if (backends.length > 1) {
    return { entries, error: `repos lists ${backends.length} backends (${backends.map((b) => b.path).join(', ')}); a run takes zero or one. Fix: run once per backend, or mark the others with another role.` }
  }
  return { entries, error: '' }
}

/**
 * One dev URL per frontend repo: the matching args.repos entry's url, else (with a single frontend) the url
 * argument, else the repo's own devUrl, else its manifest default. Two frontends on the same URL are refused.
 * @param {object[]} repos detected repos
 * @param {{ path: string, url?: string }[]} entries normalizeRepoHints entries
 * @param {string|null} hint the url argument
 * @returns {{ targets: { repo: object, url: string }[], error: string }}
 */
export function frontendTargets(repos, entries, hint) {
  const same = (a, b) => String(a).replace(/^\.\//, '').replace(/\/+$/, '') === String(b).replace(/^\.\//, '').replace(/\/+$/, '')
  const fronts = (repos || []).filter(isFrontendRepo)
  const given = runUrlHint(hint, fronts.length === 1 ? fronts[0].reportedDevHosts : undefined)
  const targets = []
  for (const repo of fronts) {
    const entry = (entries || []).find((e) => same(e.path, repo.path))
    if (entry && entry.url !== undefined && !isDevUrl(entry.url, repo.reportedDevHosts)) {
      return { targets, error: `The url for ${repo.path} is not a local development URL. Fix: pass http://localhost:<port> (or another local host) as that entry's url.` }
    }
    targets.push({ repo, url: (entry && entry.url) || (fronts.length === 1 && given) || repoDevUrl(repo) })
  }
  const seen = new Map()
  for (const t of targets) {
    if (!t.url) continue
    if (seen.has(t.url)) {
      return { targets, error: `Frontends ${seen.get(t.url)} and ${t.repo.path} resolve to the same url ${t.url}. Fix: pass a distinct url for each in args.repos, or run them separately.` }
    }
    seen.set(t.url, t.repo.path)
  }
  return { targets, error: '' }
}

// Prompt fragment naming each frontend and its URL when a run has several; '' for zero or one.
export function frontendPassesLine(targets) {
  if (!targets || targets.length < 2) return ''
  return targets.map((t) => `${t.repo.path} (${t.repo.stack}) at ${t.url || 'a URL you discover'}`).join('; ')
}

/**
 * The URL a repo's build-gate guard checks: its own frontend target's URL, else the run's URL. With several
 * frontends each gate agent must watch its own dev server, not the first frontend's.
 * @param {object} repo a detected repo
 * @param {{ repo: object, url: string }[]} targets frontendTargets(...).targets
 * @param {string} fallback the run-wide URL (or a placeholder)
 * @returns {string}
 */
export function gateDevUrlFor(repo, targets, fallback) {
  const target = repo && (targets || []).find((t) => t.repo.path === repo.path)
  return (target && target.url) || fallback
}

/**
 * Splits changed files across frontend targets. A file belongs to the repo whose path is its longest prefix
 * ("." claims any path no other repo does); files of a non-frontend repo are dropped. A file no repo claims
 * (an absolute or repo-relative path) is given to every target, so an ambiguous change is checked, not skipped.
 * @param {{ repo: object, url: string }[]} targets frontendTargets(...).targets
 * @param {string[]} files changed file paths, relative to the current directory
 * @param {object[]} [repos] every detected repo, so a backend's files are not mistaken for unclaimed ones
 * @returns {{ repo: object, url: string, files: string[] }[]} the targets in order, each with its files
 * @example frontendChanges([{ repo: { path: '../web' } }, { repo: { path: '../admin' } }], ['../web/app/page.tsx'])
 *   // [{ ..., files: ['../web/app/page.tsx'] }, { ..., files: [] }]
 */
export function frontendChanges(targets, files, repos) {
  const norm = (p) => String(p || '').replace(/^(\.\/)+/, '').replace(/\/+$/, '')
  const list = targets || []
  const roots = list.map((t) => norm(t.repo.path))
    .concat((repos || []).filter((r) => !list.some((t) => norm(t.repo.path) === norm(r.path))).map((r) => norm(r.path)))
  const owned = list.map(() => [])
  const shared = []
  for (const file of files || []) {
    const f = norm(file)
    let best = -1
    let bestLength = -1
    roots.forEach((root, i) => {
      const anywhere = root === '.' || root === ''
      const length = anywhere ? 0 : root.length
      if ((anywhere || f === root || f.startsWith(`${root}/`)) && length > bestLength) {
        best = i
        bestLength = length
      }
    })
    if (best < 0) shared.push(file)
    else if (best < list.length) owned[best].push(file)
  }
  return list.map((t, i) => ({ ...t, files: owned[i].concat(shared) }))
}

/**
 * Runs one browser pass per target, one after another. Every pass drives the session's single browser
 * (one Playwright MCP server, or Claude in Chrome), so concurrent passes would race on its page, viewport
 * and console log.
 * @param {object[]} targets the frontends to visit, in order
 * @param {(target: object) => Promise<object|null>} runPass starts the pass for one target
 * @returns {Promise<(object|null)[]>} each pass's result, in target order
 */
export async function sequentialPasses(targets, runPass) {
  const results = []
  for (const target of targets || []) results.push(await runPass(target))
  return results
}

/**
 * Merges per-frontend acceptance results into one: resolved only when every pass returned and resolved;
 * steps, unchanged behaviors and reasons are tagged with their repo path; passes lists each repo's outcome.
 * @param {{ repo: object, url: string }[]} targets the frontends, in pass order
 * @param {(object|null)[]} results each pass's ACCEPTANCE_SCHEMA result (null when the pass did not return)
 * @returns {object} an ACCEPTANCE_SCHEMA result with an extra passes array
 */
export function mergeAcceptancePasses(targets, results) {
  const tag = (i, text) => `[${targets[i].repo.path}] ${text}`
  const merged = {
    resolved: results.length > 0 && results.every((r) => !!(r && r.resolved)),
    steps: results.flatMap((r, i) => ((r && r.steps) || []).map((s) => ({ ...s, step: tag(i, s.step) }))),
    brokenLinks: Array.from(new Set(results.flatMap((r) => (r && r.brokenLinks) || []))),
    reason: results.map((r, i) => (!r ? tag(i, 'the acceptance pass did not return') : r.reason ? tag(i, r.reason) : '')).filter(Boolean).join(' '),
    passes: targets.map((t, i) => ({ repo: t.repo.path, url: t.url, resolved: !!(results[i] && results[i].resolved) })),
  }
  if (results.some((r) => r && Array.isArray(r.unchanged))) {
    merged.unchanged = results.flatMap((r, i) => ((r && r.unchanged) || []).map((u) => ({ ...u, behavior: tag(i, u.behavior) })))
  }
  return merged
}

// Prompt fragment for the app URL: the URL, or the instruction to discover and probe one.
export function appUrlLine(devUrl) {
  return devUrl || `none declared — discover the dev server URL (the repo's dev script, its config) and probe it; if nothing responds, report the browser check as ${NO_APP_URL}`
}

// Renders the Detect-phase catalog straight from the registry so the detector
// agent is told about every stack without any stack prose living in the prompt.
export function stackCatalog() {
  const known = STACK_KEYS.filter((k) => k !== 'other').map((k) => {
    const s = STACKS[k]
    const extras = hasOwn(STACK_EXTRAS, k) ? STACK_EXTRAS[k] : {}
    const skipRules = (extras.gates || {})
    const gates = s.gates.length
      ? s.gates.map((g) => `{${g.name}: ${g.command}${skipRules[g.name] && skipRules[g.name].unless ? ` — skip when any of ${skipRules[g.name].unless.join(', ')} exists` : ''}}`).join(', ')
      : '(whatever lint/test tooling exists)'
    const pms = (extras.packageManagers || []).map((p) => `${p.lockfiles.join(' or ')} → packageManager ${p.name} (<pm> = ${p.run}, <pmx> = ${p.exec || p.run})`)
    const pmLine = pms.length ? ` package managers (record packageManager from the lockfile; no lockfile → ${extras.packageManagers[extras.packageManagers.length - 1].name}; write gateCommands with <pm>/<pmx> replaced by the real commands): ${pms.join('; ')}.` : ''
    return `- ${k} — detect: ${s.detect}. specialistAgent: ${s.agent}. conventions: ${s.conventions.join(', ') || '(infer)'}. gateCommands (only those whose tool actually exists): ${gates}. debug patterns: ${s.debugPatterns.join(' ')}.${isDevUrl(s.devUrl) ? ` devUrl default ${s.devUrl}.` : ''}${pmLine}`
  })
  known.push(`- other — anything unrecognized; specialistAgent: general-purpose; conventions = whatever actually exists. gateCommands only from these templates, one item per script or target the evidence file defines, as {name, command, evidence, script} (evidence = the file relative to the repo root, script = the script or target name, command = the template with {script} replaced): ${gateTemplatesLine()}. Any other command is dropped.`)
  return known.join('\n')
}

// Model tiers. Phases name a tier, never a model, and every agent() call gets
// the tier's model AND effort explicitly — an agentType agent otherwise
// inherits its own frontmatter model, and effort falls back to the session
// default (which changes between releases).
// Aliases follow each new release, which suits personal use. For team
// reproducibility, distribute a version with full model IDs here
// (e.g. 'claude-opus-5-5'), or pin per run: args.models = { deep: 'claude-opus-5-5' }
// or { deep: { model: 'claude-opus-5-5', effort: 'xhigh' } }.
export const MODEL_TIERS = {
  deep: { model: 'opus', effort: 'high' }, // investigation, specs, review, acceptance, decisions
  standard: { model: 'sonnet', effort: 'medium' }, // implementation, fixes, gates, verification votes
  light: { model: 'haiku', effort: 'low' }, // inventory and other mechanical work
}
export function phaseModels(phaseTiers) {
  const overrides = (typeof args !== 'undefined' && args && typeof args === 'object' && args.models) || {}
  const resolved = {}
  for (const [phase, tier] of Object.entries(phaseTiers)) {
    const base = MODEL_TIERS[tier]
    if (!base) throw new Error(`Unknown model tier "${tier}" for phase "${phase}" (use ${Object.keys(MODEL_TIERS).join(' | ')})`)
    const o = overrides[tier]
    // A bridge host picks its own models, so its jobs carry the tier and the effort only.
    if (HOST !== 'claude') {
      resolved[phase] = { tier, effort: (o && typeof o === 'object' && o.effort) || base.effort }
      continue
    }
    resolved[phase] = typeof o === 'string' ? { ...base, model: o } : { ...base, ...(o || {}) }
  }
  return resolved
}

// Every step that may need a browser gets the same instructions: Playwright MCP
// first (built in), Claude in Chrome as a fallback, and an honest "not run".
export const BROWSER_PHASES = new Set(['Reproduce', 'Acceptance', 'Visual'])
export const BROWSER_GUIDE = `BROWSER: when this step needs a browser (web UI, navigation, visual or end-to-end checks), drive it with the Playwright MCP tools, named mcp__playwright__browser_* when the server comes from the project and mcp__plugin_sdd-kit_playwright__browser_* when it comes from the sdd-kit plugin (use whichever is available): browser_navigate, browser_snapshot, browser_click, browser_type, browser_fill_form, browser_wait_for, browser_take_screenshot, browser_console_messages, browser_network_requests, browser_resize (load each with ToolSearch "select:<name>" before its first call). Assert against browser_snapshot (the accessibility tree), use screenshots only as evidence, and check console errors and failed network requests on every page you visit. If the Playwright tools are unavailable, use Claude in Chrome (mcp__claude-in-chrome__*). If neither is available, report the browser check as not run — never claim it passed. API-only checks use HTTP (curl) instead of a browser.`
// The host reaches the runtime only through the sddHost global that the workflow bridge injects;
// Claude Code has no bridge, so the global is absent and the registry text below applies unchanged.
export const HOST = typeof sddHost === 'string' && hasOwn(HOSTS, sddHost) ? sddHost : 'claude'
export const browserGuideFor = () => HOSTS[HOST].browserGuide || BROWSER_GUIDE
// Where the host keeps project stacks, user stacks, agents and its trust store; Claude's values reproduce the text below unchanged.
export const HOST_STACKS_DIR = HOSTS[HOST].stacksDir
export const HOST_USER_STACKS_DIR = `~/${HOSTS[HOST].configDir}/stacks`
// A bridge host resolves specialists from the kit and from approved stack add-ons only, never from its own agents folder.
export const addAgentHint = (name) => (HOST === 'claude'
  ? `add ${name}.md to ${HOSTS[HOST].agentsDir}/`
  : `add ${name}.md to agents/ of an approved stack add-on under ${HOSTS[HOST].stackAddonsDir}/`)
export const HOST_TRUST_STORE_DIR = HOSTS[HOST].trustStoreDir.replace('<OS home>', '<home>')
export const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')
// Plugin installs namespace agents ("sdd-kit:code-explorer", "<plugin>:<agent>");
// file-copy installs use bare names. Detect reports which one this run sees as
// discovery.mode (resolveDetect records it), and the candidates follow it so a pure
// install resolves every agent on the first try. The default agent is the last resort:
//   - a core agent (CORE_AGENTS): "sdd-kit:<name>" and the bare name;
//   - a stack specialist (AGENT_INFO): the bare name and "<plugin>:<name>", the latter only when its manifest sets agent.plugin;
//   - general-purpose is never resolved.
// "plugin" puts the namespaced form first, "file-copy" the bare name. "mixed", "unknown",
// "none" and every call made before Detect returns keep the default order: the namespaced
// form first for a core agent, the bare name first for a specialist.
// A candidate fails only when agent() throws (unknown agent type). A null result is the agent's own
// outcome (skipped, or ended without output) and is returned, so a resolved prompt never runs twice.
// The resolution (the form that worked, or null for the default agent) is kept per agent name for the
// run, so later calls go straight to the resolved form and the fallback is logged once. A form that
// worked is known only when its whole agent run returns, so calls that start together do not wait for
// it: each tries the candidates itself, skipping the forms an earlier call saw rejected.
export const resolvedAgents = new Map()
export const rejectedAgentTypes = new Set()
export let discoveryMode = null

/**
 * Agent counts and token totals per phase for the run report.
 * phases[name] = { agents, tokens }: agents counts runAgent calls made with opts.phase = name
 * ('unphased' when absent); tokens is the budget spent while the phase was the current
 * costSnapshot phase, or null when the run has no budget. probesFailed counts candidate
 * names agent() rejected while resolving an agent type.
 */
export const RUN_COST = { phases: {}, probesFailed: 0 }
export let costMark = null

export function costPhase(name) {
  if (!hasOwn(RUN_COST.phases, name)) RUN_COST.phases[name] = { agents: 0, tokens: null }
  return RUN_COST.phases[name]
}

export const runBudget = () => (typeof budget !== 'undefined' && budget && budget.total > 0 ? budget : null)

/**
 * Closes the current cost phase and opens `name`. Call it right after each main-line phase()
 * call, with the same title. The budget spent since the previous snapshot is added to the
 * previous phase, so a phase that repeats (a fix loop) accumulates. With no budget
 * (budget.total 0, as on the bridge) tokens stay null and the report prints "tokens: n/a".
 * @param {string} name the phase being entered
 * @returns {void}
 * @example
 * phase('Build'); costSnapshot('Build')
 */
export function costSnapshot(name) {
  const b = runBudget()
  const remaining = b ? b.remaining() : null
  if (costMark && b && costMark.remaining !== null) {
    const entry = costPhase(costMark.phase)
    entry.tokens = (entry.tokens || 0) + Math.max(0, costMark.remaining - remaining)
  }
  costPhase(name)
  costMark = { phase: name, remaining }
}

/**
 * Candidate agent types for `name`, in the order runAgent tries them.
 * @param {string} name agent name without a plugin prefix
 * @param {string|null} [mode] Detect's discovery.mode; null (before Detect) keeps the default order
 * @returns {{ candidates: string[], hint: string }} hint: what to install or add when none resolves
 */
export function agentCandidates(name, mode = discoveryMode) {
  if (CORE_AGENTS.includes(name)) {
    const candidates = mode === 'file-copy' ? [name, `sdd-kit:${name}`] : [`sdd-kit:${name}`, name]
    return { candidates, hint: 'reinstall sdd-kit (core agent missing)' }
  }
  if (hasOwn(AGENT_INFO, name)) {
    const info = AGENT_INFO[name]
    const namespaced = info.plugin ? [`${info.plugin}:${name}`] : []
    const candidates = mode === 'plugin' ? [...namespaced, name] : [name, ...namespaced]
    const stacks = info.stacks.join(', ')
    const hint = info.plugin
      ? `install ${info.plugin} for ${stacks}`
      : `${addAgentHint(name)}${info.source ? ` or set agent.plugin in ${info.source}` : ''}`
    return { candidates, hint }
  }
  return { candidates: [name], hint: addAgentHint(name) }
}

/**
 * Runs `prompt` through agent() with the agent type resolved for this install, adds the
 * browser guide to browser phases, and counts the call under opts.phase in RUN_COST.
 * @param {string} prompt
 * @param {object} [opts] agent() options; agentType is a bare agent name
 * @returns {Promise<*>} the agent's result
 */
export async function runAgent(prompt, opts) {
  costPhase((opts && opts.phase) || 'unphased').agents += 1
  if (opts && BROWSER_PHASES.has(opts.phase)) prompt = `${prompt}\n\n${browserGuideFor()}`
  if (!opts || !opts.agentType || opts.agentType === 'general-purpose') return agent(prompt, opts)
  const name = opts.agentType
  const { agentType, ...rest } = opts
  if (resolvedAgents.has(name)) {
    const known = resolvedAgents.get(name)
    return known === null ? agent(prompt, rest) : agent(prompt, { ...opts, agentType: known })
  }
  const { candidates, hint } = agentCandidates(name)
  for (const candidate of candidates) {
    if (rejectedAgentTypes.has(candidate)) continue
    let result
    try {
      result = await agent(prompt, { ...opts, agentType: candidate })
    } catch (e) {
      // Unknown agent type in this install mode; try the next form.
      rejectedAgentTypes.add(candidate)
      RUN_COST.probesFailed += 1
      continue
    }
    if (!resolvedAgents.has(name)) resolvedAgents.set(name, candidate)
    return result
  }
  if (!resolvedAgents.has(name)) {
    resolvedAgents.set(name, null)
    log(`Specialist ${name} not available (tried: ${candidates.join(', ')}); ${hint}. Falling back to general-purpose.`)
  }
  return agent(prompt, rest)
}

// --- manifest validation ------------------------------------------------
// One validator for the generator and the runtime. It interprets STACK_SCHEMA
// (type, required, enum, additionalProperties, properties, items, pattern and
// oneOf) and adds the rules a schema cannot express. Problems come back in
// validation order as { pointer, rule, problem, fix }; the caller formats them as
// "<pointer> <problem>. Fix: <fix>". problem and fix may quote manifest values; rule
// never does, so text that reaches a prompt is built from pointer and rule only (redactedReason).
export function manifestTypeOf(v) {
  if (Array.isArray(v)) return 'array'
  if (v === null) return 'null'
  if (Number.isInteger(v)) return 'integer'
  return typeof v
}

export const manifestPointer = (parent, key) => `${parent}/${String(key).replace(/~/g, '~0').replace(/\//g, '~1')}`

export function manifestSchemaCheck(value, schema, ptr, overlay, out) {
  const at = ptr || '/'
  const actual = manifestTypeOf(value)
  if (schema.oneOf) {
    const branch = schema.oneOf.find((b) => b.type === actual)
    if (!branch) {
      out.push({ pointer: at, rule: 'type', problem: `has the wrong type (found ${actual})`, fix: `use ${schema.oneOf.map((b) => `an ${b.type}`).join(' or ')}` })
      return
    }
    manifestSchemaCheck(value, branch, ptr, overlay, out)
    return
  }
  if (schema.type) {
    const ok = schema.type === actual || (schema.type === 'number' && actual === 'integer')
    if (!ok) {
      out.push({ pointer: at, rule: 'type', problem: `has the wrong type (found ${actual})`, fix: `use a ${schema.type}` })
      return
    }
  }
  if (schema.enum && !schema.enum.some((e) => e === value)) {
    out.push({ pointer: at, rule: 'enum', problem: `has the invalid value ${JSON.stringify(value)}`, fix: `use one of: ${schema.enum.map((e) => JSON.stringify(e)).join(', ')}` })
  }
  if (typeof value === 'string') {
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) {
      out.push({ pointer: at, rule: 'pattern', problem: `does not match the pattern (found ${JSON.stringify(value)})`, fix: `match ${schema.pattern}` })
    }
    if (overlay && value.length > STACK_LIMITS.maxString) {
      out.push({ pointer: at, rule: 'maxLength', problem: `is longer than ${STACK_LIMITS.maxString} characters`, fix: 'shorten it' })
    }
  }
  if (actual === 'object' && schema.properties) {
    // An extending overlay refines a first-party stack, so it needs only its identity.
    const required = overlay && hasOwn(schema.properties, 'extends') && hasOwn(value, 'extends') ? schema.required.filter((k) => ['name', 'order'].includes(k)) : schema.required || []
    for (const key of required) {
      if (!hasOwn(value, key)) out.push({ pointer: manifestPointer(ptr, key), rule: 'required', problem: 'is missing', fix: `add "${key}"` })
    }
    for (const key of Object.keys(value)) {
      if (!hasOwn(schema.properties, key)) {
        if (schema.additionalProperties === false) {
          out.push({ pointer: manifestPointer(ptr, key), rule: 'additionalProperties', problem: 'is not an allowed key', fix: `remove "${key}" (allowed: ${Object.keys(schema.properties).join(', ')})` })
        }
      } else {
        manifestSchemaCheck(value[key], schema.properties[key], manifestPointer(ptr, key), overlay, out)
      }
    }
  }
  if (actual === 'array') {
    if (schema.minItems !== undefined && value.length < schema.minItems) {
      out.push({ pointer: at, rule: 'minItems', problem: `has fewer than ${schema.minItems} items`, fix: 'add an item' })
    }
    if (overlay && value.length > STACK_LIMITS.maxItems) {
      out.push({ pointer: at, rule: 'maxItems', problem: `has more than ${STACK_LIMITS.maxItems} items`, fix: 'remove items' })
    }
    if (schema.items) value.forEach((item, i) => manifestSchemaCheck(item, schema.items, manifestPointer(ptr, i), overlay, out))
  }
}

// Rules per entry that the schema cannot express: unique keys in an array
// manifest, the 1-8 entry bound, where agent.plugin is allowed, and that only
// the core other manifest declares gateTemplates.
export function manifestEntryRules(value, overlay, out) {
  const isList = Array.isArray(value)
  const entries = isList ? value : [value]
  if (isList && (value.length < 1 || value.length > STACK_LIMITS.maxEntries)) {
    out.push({ pointer: '/', rule: 'entryCount', problem: `must hold 1 to ${STACK_LIMITS.maxEntries} entries`, fix: 'split the manifest' })
  }
  const seen = new Set()
  entries.forEach((entry, i) => {
    if (manifestTypeOf(entry) !== 'object') return
    const ptr = isList ? `/${i}` : ''
    if (typeof entry.name === 'string') {
      if (seen.has(entry.name)) out.push({ pointer: `${ptr}/name`, rule: 'uniqueKeys', problem: `duplicates key "${entry.name}" in this file`, fix: 'use unique keys' })
      seen.add(entry.name)
    }
    if (hasOwn(entry, 'gateTemplates') && (overlay || entry.name !== 'other')) {
      out.push({ pointer: `${ptr}/gateTemplates`, rule: 'gateTemplates', problem: 'is reserved for the core other manifest', fix: 'remove "gateTemplates" and list the gates under "gates"' })
    }
    if (overlay && hasOwn(entry, 'devUrlHosts')) {
      out.push({ pointer: `${ptr}/devUrlHosts`, rule: 'additionalProperties', problem: 'is not an allowed key', fix: 'remove it (stack.schema.json lists the allowed keys)' })
    }
    if (overlay && hasOwn(entry, 'extends')) {
      if (typeof entry.extends === 'string' && (!FIRST_PARTY_KEYS.includes(entry.extends) || entry.extends === 'other')) {
        out.push({ pointer: `${ptr}/extends`, rule: 'extendsTarget', problem: 'names a stack that cannot be extended', fix: `name a first-party key other than "other", for example "${EXTENDS_EXAMPLE}"` })
      }
      if (FIRST_PARTY_KEYS.includes(entry.name)) {
        out.push({ pointer: `${ptr}/name`, rule: 'extendsName', problem: 'is a first-party key', fix: 'give the overlay its own key, for example "<key>-local"' })
      }
      for (const field of ['detect', 'markers', 'packages', 'role']) {
        if (hasOwn(entry, field)) out.push({ pointer: `${ptr}/${field}`, rule: 'extendsField', problem: 'is not allowed in an extending overlay', fix: 'remove it; classification comes from the extended stack' })
      }
    }
    if (!overlay && hasOwn(entry, 'extends')) {
      out.push({ pointer: `${ptr}/extends`, rule: 'additionalProperties', problem: 'is not an allowed key', fix: 'remove it (stack.schema.json lists the allowed keys)' })
    }
    const agent = entry.agent
    if (overlay && manifestTypeOf(agent) === 'object' && CORE_AGENTS.includes(agent.name)) {
      out.push({ pointer: `${ptr}/agent/name`, rule: 'coreAgent', problem: `names the core agent "${agent.name}"`, fix: 'name your own specialist, for example "<stack>-dev"' })
    }
    if (manifestTypeOf(agent) !== 'object' || !hasOwn(agent, 'plugin')) return
    if (agent.name === 'general-purpose') {
      out.push({ pointer: `${ptr}/agent/plugin`, rule: 'agentPlugin', problem: 'is not allowed for general-purpose', fix: 'remove "plugin"' })
    } else if (overlay && agent.plugin === 'sdd-kit') {
      out.push({ pointer: `${ptr}/agent/plugin`, rule: 'corePlugin', problem: 'names the core plugin "sdd-kit"', fix: "set your add-on's plugin name" })
    }
  })
}

/**
 * Validates a parsed stack manifest (one entry object, or an array of entries).
 * @param {unknown} value the parsed JSON
 * @param {{ overlay?: boolean }} [options] overlay: also apply the string, item and agent.plugin limits that guard project and user manifests
 * @returns {{ pointer: string, rule: string, problem: string, fix: string }[]} every problem, empty when valid
 */
export function validateStackManifest(value, options) {
  const overlay = !!(options && options.overlay)
  const out = []
  manifestSchemaCheck(value, STACK_SCHEMA, '', overlay, out)
  manifestEntryRules(value, overlay, out)
  return out
}

// --- canonical JSON, sha256 and trust ----------------------------------------
// Workflow scripts cannot import modules, so the hash that identifies a manifest
// is computed here without crypto. src/skills/stack-trust/scripts/trust-store.mjs
// uses node:crypto over the same canonical text; tools/test/fixtures/trust-vectors.json
// pins both to the same digests.

/**
 * Serializes a JSON value with object keys sorted in code-unit order and no whitespace.
 * @param {unknown} value parsed JSON
 * @returns {string} the canonical text
 */
export function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`
  if (value !== null && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`
  }
  return JSON.stringify(value)
}

// Canonical text of a parsed manifest: `$schema` is dropped from the top-level object, or from each top-level element of an array.
export function canonicalManifest(parsed) {
  const strip = (e) => {
    if (e === null || typeof e !== 'object' || Array.isArray(e) || !hasOwn(e, '$schema')) return e
    const { $schema, ...rest } = e
    return rest
  }
  return canonicalJson(Array.isArray(parsed) ? parsed.map(strip) : strip(parsed))
}

export const SHA256_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]

// UTF-8 bytes of a string; a lone surrogate encodes as U+FFFD, as node does.
export function utf8Bytes(text) {
  const bytes = []
  for (const ch of text) {
    let c = ch.codePointAt(0)
    if (c >= 0xd800 && c <= 0xdfff) c = 0xfffd
    if (c < 0x80) bytes.push(c)
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63))
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63))
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63))
  }
  return bytes
}

/**
 * SHA-256 of a string's UTF-8 bytes, as lowercase hex.
 * @param {string} text
 * @returns {string} 64 hex characters
 */
export function sha256Hex(text) {
  const bytes = utf8Bytes(text)
  const bitLength = bytes.length * 8
  bytes.push(0x80)
  while (bytes.length % 64 !== 56) bytes.push(0)
  const high = Math.floor(bitLength / 0x100000000)
  const low = bitLength >>> 0
  for (const word of [high, low]) bytes.push((word >>> 24) & 255, (word >>> 16) & 255, (word >>> 8) & 255, word & 255)
  const h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]
  const w = new Array(64)
  const rotr = (x, n) => (x >>> n) | (x << (32 - n))
  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let i = 0; i < 16; i++) {
      const j = offset + i * 4
      w[i] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3)
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10)
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0
    }
    let [a, b, c, d, e, f, g, hh] = h
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + SHA256_K[i] + w[i]) >>> 0
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0
      hh = g
      g = f
      f = e
      e = (d + t1) >>> 0
      d = c
      c = b
      b = a
      a = (t1 + t2) >>> 0
    }
    const next = [a, b, c, d, e, f, g, hh]
    for (let i = 0; i < 8; i++) h[i] = (h[i] + next[i]) >>> 0
  }
  return h.map((x) => x.toString(16).padStart(8, '0')).join('')
}

// Hash that identifies a manifest (file or entry) in the trust store and in FIRST_PARTY_HASHES.
export const manifestHash = (parsed) => sha256Hex(canonicalManifest(parsed))

// Approved hashes from the trust store text Detect read. A store that is present but does not parse approves nothing.
export function parseTrustStore(text) {
  if (text === null || text === undefined) return { hashes: new Set(), unreadable: false }
  try {
    const store = JSON.parse(text)
    if (store && typeof store === 'object' && Array.isArray(store.trusted)) {
      return { hashes: new Set(store.trusted.map((t) => t && t.sha256).filter((h) => typeof h === 'string')), unreadable: false }
    }
  } catch (e) {
    // falls through to unreadable
  }
  return { hashes: new Set(), unreadable: true }
}

// --- overlay: third-party manifests merged over the inlined registry ----------
// Workflow scripts cannot read files, so Detect returns raw manifest text and this code
// validates, deduplicates and trusts it. First-party entries are inlined and always win.

export const DISCOVERY_MODES = ['plugin', 'file-copy', 'mixed', 'unknown', 'none']
export const DISCOVERY_METHODS = ['plugin-list', 'installed-plugins', 'cache-sweep', 'stacks-dir', 'none']
export const SCOPE_RANK = { project: 0, plugin: 1, user: 2 }
export const STALE_FIX = {
  file: 're-run install.sh to refresh it',
  plugin: (plugin) => `update sdd-kit and ${plugin} to the same version`,
}

export const problemReason = (p) => `${p.pointer} ${p.problem}. Fix: ${p.fix}`

// What each validation rule means, as the run reports it. A rejected manifest's reason carries its JSON
// pointer, the rule name and this fixed text; no value, key or other text of the manifest reaches a prompt.
export const RULE_TEXT = {
  type: ['has the wrong type', 'use the type stack.schema.json gives for it'],
  enum: ['has a value outside the allowed list', 'use one of the values stack.schema.json lists for it'],
  pattern: ['does not match its pattern', 'match the pattern stack.schema.json gives for it'],
  maxLength: [`is longer than ${STACK_LIMITS.maxString} characters`, 'shorten it'],
  required: ['is missing', 'add it'],
  additionalProperties: ['is not an allowed key', 'remove it (stack.schema.json lists the allowed keys)'],
  minItems: ['has too few items', 'add an item'],
  maxItems: [`has more than ${STACK_LIMITS.maxItems} items`, 'remove items'],
  entryCount: [`must hold 1 to ${STACK_LIMITS.maxEntries} entries`, 'split the manifest'],
  uniqueKeys: ['duplicates another key in this file', 'use unique keys'],
  gateTemplates: ['is reserved for the core other manifest', 'remove "gateTemplates" and list the gates under "gates"'],
  coreAgent: ['names a core agent', 'name your own specialist, for example "<stack>-dev"'],
  agentPlugin: ['is not allowed for general-purpose', 'remove "plugin"'],
  corePlugin: ['names the core plugin "sdd-kit"', "set your add-on's plugin name"],
  extendsTarget: ['names a stack that cannot be extended', `name a first-party key other than "other", for example "${EXTENDS_EXAMPLE}"`],
  extendsName: ['is a first-party key', 'give the overlay its own key, for example "<key>-local"'],
  extendsField: ['is not allowed in an extending overlay', 'remove it; classification comes from the extended stack'],
  json: ['is not valid JSON', 'correct the JSON syntax'],
  maxSize: [`is larger than ${STACK_LIMITS.maxRawLength / 1024} KB`, 'shorten the manifest'],
}

// Every property name the schema declares; a pointer segment that is neither one of these nor an array index
// is a key the manifest chose, and is reported as <key>.
export const SCHEMA_KEY_NAMES = (() => {
  const names = new Set()
  const walk = (node) => {
    if (Array.isArray(node)) return node.forEach(walk)
    if (node === null || typeof node !== 'object') return
    if (node.properties) for (const k of Object.keys(node.properties)) names.add(k)
    for (const v of Object.values(node)) walk(v)
  }
  walk(STACK_SCHEMA)
  return names
})()

/**
 * A rejection reason as the run reports it: the problem's JSON pointer (manifest-chosen keys replaced by
 * <key>), the rule it breaks and that rule's fixed text.
 * @param {{ pointer: string, rule: string }} p a validator problem, or { pointer: '/', rule: 'json' | 'maxSize' }
 * @returns {string} for example '/role has a value outside the allowed list (rule enum). Fix: use one of the values stack.schema.json lists for it'
 */
export function redactedReason(p) {
  const pointer = !p.pointer || p.pointer === '/' ? '/' : p.pointer.split('/').map((seg, i) => (i === 0 || /^\d{1,3}$/.test(seg) || SCHEMA_KEY_NAMES.has(seg) ? seg : '<key>')).join('/')
  const rule = hasOwn(RULE_TEXT, p.rule) ? p.rule : 'schema'
  const [problem, fix] = hasOwn(RULE_TEXT, rule) ? RULE_TEXT[rule] : ['breaks the manifest schema', 'check the manifest against stack.schema.json']
  return `${pointer} ${problem} (rule ${rule}). Fix: ${fix}`
}
export const SOURCE_LABEL_PATTERN = /^[A-Za-z0-9:._~/@-]{1,120}$/

// The source labels Detect may report. Anything else is rejected before its text is read.
export const MANIFEST_SOURCE_FORMS = [
  new RegExp(`^project:${escapeRegex(HOST_STACKS_DIR)}/[^/\\\\\\s]+$`),
  new RegExp(`^user:${escapeRegex(HOST_USER_STACKS_DIR)}/[^/\\\\\\s]+$`),
  /^plugin:[A-Za-z0-9][A-Za-z0-9._-]*@[A-Za-z0-9._-]+$/,
]
export const MISSING_SOURCE = `missing or invalid source. Fix: report source as project:${HOST_STACKS_DIR}/<file>, user:${HOST_USER_STACKS_DIR}/<file> or plugin:<name>@<marketplace>`
// A label must pass SOURCE_LABEL_PATTERN as well as one of the forms: it is pasted into prompts and logs.
export const isManifestSource = (source) => SOURCE_LABEL_PATTERN.test(source) && MANIFEST_SOURCE_FORMS.some((re) => re.test(source))
export const STACK_KEY_PATTERN = /^[a-z][a-z0-9-]{1,31}$/

// Which add-on directory a manifest source stands in for, or null when the source is not a first-party location.
export function firstPartyLocation(source) {
  const colon = source.indexOf(':')
  const scope = colon > 0 ? source.slice(0, colon) : ''
  const rest = source.slice(colon + 1)
  let dir = null
  let plugin = null
  if (scope === 'project') {
    const m = new RegExp(`^${escapeRegex(HOST_STACKS_DIR)}/([^/]+)\\.json$`).exec(rest)
    dir = m && m[1]
  } else if (scope === 'user') {
    const m = new RegExp(`^${escapeRegex(HOST_USER_STACKS_DIR)}/([^/]+)\\.json$`).exec(rest)
    dir = m && m[1]
  } else if (scope === 'plugin') {
    plugin = rest.split('@')[0]
    dir = FIRST_PARTY_PLUGINS.includes(plugin) ? plugin.replace(/^sdd-kit-/, '') : null
  }
  if (!dir || !hasOwn(FIRST_PARTY_FILES, dir)) return null
  return { dir, plugin, kind: scope === 'plugin' ? 'plugin' : 'file' }
}

export const manifestEntries = (parsed) => (Array.isArray(parsed) ? parsed : [parsed])

export const entryName = (e) => (e !== null && typeof e === 'object' && typeof e.name === 'string' ? e.name : null)

/**
 * Validates Detect's manifests and decides which keys join the registry.
 * Pure: nothing is installed until installOverlay(result) runs.
 * A first-party location may come back as { source, sha256 } (the canonical hash, no text): it is present
 * when the hash equals FIRST_PARTY_FILE_HASHES for its add-on, a stale copy otherwise.
 * @param {{ source: string, raw?: string, sha256?: string }[]} manifests manifest files from Detect
 * @param {string|null} trustStoreText verbatim trust store text, null when absent
 * A manifest without a string source, or with a source outside the forms in MANIFEST_SOURCE_FORMS, is
 * rejected and its text is never parsed. declinedKeys maps every stack key a rejected manifest names to the
 * reason, and unnamedRejections lists the rejected manifests whose keys could not be read, so resolveRepo can
 * report a repo of such a stack as not run.
 * @returns {{ present: string[], added: { key: string, source: string }[], ignored: { key: string, source: string, reason: string }[], rejected: { source: string, reason: string, firstParty: boolean }[], entries: object, keys: string[], untrusted: { source: string, keys: string[], sha256: string }[], logs: string[], storeUnreadable: boolean, declinedKeys: Object<string, string>, unnamedRejections: string[] }}
 */
export function mergeOverlay(manifests, trustStoreText) {
  const present = []
  const ignored = []
  const rejected = []
  const logs = []
  const stale = []
  const candidates = []
  const trust = parseTrustStore(trustStoreText)
  const declinedKeys = {}
  const unnamedRejections = []
  const declineKeys = (value, reason) => {
    for (const e of manifestEntries(value)) {
      const key = entryName(e)
      if (key !== null && STACK_KEY_PATTERN.test(key) && !hasOwn(declinedKeys, key)) declinedKeys[key] = reason.slice(0, 300)
    }
  }

  const markStale = (source, where, keys) => {
    const fix = where.kind === 'plugin' ? STALE_FIX.plugin(where.plugin) : STALE_FIX.file
    for (const key of keys) ignored.push({ key, source, reason: `first-party key (stale or edited copy; ${fix})` })
    stale.push({ source, kind: where.kind, fix })
  }

  for (const m of Array.isArray(manifests) ? manifests : []) {
    if (!m || typeof m !== 'object' || typeof m.source !== 'string' || !isManifestSource(m.source)) {
      const label = m && typeof m === 'object' && typeof m.source === 'string' ? (SOURCE_LABEL_PATTERN.test(m.source) ? m.source : '(invalid source)') : '(no source)'
      rejected.push({ source: label, reason: MISSING_SOURCE, firstParty: false })
      unnamedRejections.push(label)
      logs.push(`Stack manifest rejected: ${label} — ${MISSING_SOURCE}`)
      continue
    }
    const source = m.source
    const where = firstPartyLocation(source)
    const reject = (reason, firstParty) => {
      rejected.push({ source, reason, firstParty })
      logs.push(`Stack manifest rejected: ${source} — ${reason}`)
    }
    if (typeof m.raw !== 'string' && typeof m.sha256 === 'string') {
      if (!where) reject('/ came back as a hash, but only a first-party location may. Fix: return the manifest text as raw', false)
      else if (m.sha256 === FIRST_PARTY_FILE_HASHES[where.dir]) present.push(source)
      else markStale(source, where, FIRST_PARTY_FILES[where.dir])
      continue
    }
    const raw = typeof m.raw === 'string' ? m.raw : ''
    let parsed
    let parseError = null
    try {
      parsed = JSON.parse(raw)
    } catch (e) {
      parseError = e
    }
    if (raw.length > STACK_LIMITS.maxRawLength || parseError) {
      if (raw.length > STACK_LIMITS.maxRawLength) {
        if (!parseError) declineKeys(parsed, `${source} was rejected (larger than ${STACK_LIMITS.maxRawLength / 1024} KB)`)
        else unnamedRejections.push(source)
        reject(redactedReason({ pointer: '/', rule: 'maxSize' }), !!where)
      } else {
        unnamedRejections.push(source)
        reject(redactedReason({ pointer: '/', rule: 'json' }), !!where)
      }
      continue
    }
    const keys = manifestEntries(parsed).map(entryName)
    const firstParty = !!where && keys.every((k) => k !== null && FIRST_PARTY_FILES[where.dir].includes(k))
    const problems = validateStackManifest(parsed, { overlay: !firstParty })
    if (problems.length) {
      declineKeys(parsed, `${source} was rejected (${redactedReason(problems[0])})`)
      reject(redactedReason(problems[0]), firstParty)
      continue
    }
    if (firstParty) {
      if (manifestEntries(parsed).every((e) => FIRST_PARTY_HASHES[e.name] === manifestHash(e))) {
        present.push(source)
      } else {
        markStale(source, where, keys)
      }
      continue
    }
    const scope = source.slice(0, source.indexOf(':'))
    candidates.push({ source, rank: hasOwn(SCOPE_RANK, scope) ? SCOPE_RANK[scope] : 3, parsed, sha256: manifestHash(parsed) })
  }

  // The first valid entry for a key wins: project before plugin before user, then by source.
  candidates.sort((a, b) => a.rank - b.rank || (a.source < b.source ? -1 : a.source > b.source ? 1 : 0))
  const entries = {}
  const bySource = new Map()
  const extending = []
  const extendsMap = {}
  const untrustedExtending = []
  for (const c of candidates) {
    for (const entry of manifestEntries(c.parsed)) {
      if (hasOwn(entry, 'extends')) {
        if (trust.hashes.has(c.sha256)) {
          extending.push({ entry, c })
        } else {
          untrustedExtending.push({ source: c.source, keys: [entry.name], sha256: c.sha256, extends: entry.extends })
          logs.push(`${c.source} extends ${entry.extends} but is not trusted — using the first-party ${entry.extends} stack. Fix: run /stack-trust`)
        }
      } else if (FIRST_PARTY_KEYS.includes(entry.name)) {
        ignored.push({ key: entry.name, source: c.source, reason: 'first-party key' })
      } else if (hasOwn(entries, entry.name)) {
        ignored.push({ key: entry.name, source: c.source, reason: `duplicate key (kept ${entries[entry.name].source})` })
      } else {
        entries[entry.name] = { entry, source: c.source, sha256: c.sha256, trusted: trust.hashes.has(c.sha256) }
        if (!bySource.has(c.source)) bySource.set(c.source, [])
        bySource.get(c.source).push(entry.name)
      }
    }
  }
  // Trusted overlays that extend one key compete: the lowest order wins, then the key in code-unit order.
  extending.sort((a, b) => a.entry.order - b.entry.order || (a.entry.name < b.entry.name ? -1 : a.entry.name > b.entry.name ? 1 : 0))
  for (const { entry, c } of extending) {
    if (hasOwn(extendsMap, entry.extends)) {
      const winner = entries[extendsMap[entry.extends]]
      ignored.push({ key: entry.name, source: c.source, reason: `extends ${entry.extends}, and ${extendsMap[entry.extends]} from ${winner.source} wins (lower order, then key). Fix: give the overlay you want the lowest order, or remove the other.` })
    } else if (hasOwn(entries, entry.name)) {
      ignored.push({ key: entry.name, source: c.source, reason: `duplicate key (kept ${entries[entry.name].source})` })
    } else {
      const { extends: target, ...declared } = entry
      entries[entry.name] = { entry: { ...firstPartyEntry(target), ...declared }, source: c.source, sha256: c.sha256, trusted: true, extends: target, declared: Object.keys(declared) }
      extendsMap[target] = entry.name
      if (!bySource.has(c.source)) bySource.set(c.source, [])
      bySource.get(c.source).push(entry.name)
    }
  }
  const added = candidates.flatMap((c) => (bySource.get(c.source) || []).map((key) => (entries[key].extends ? { key, source: c.source, extends: entries[key].extends } : { key, source: c.source })))
  const untrusted = [...bySource].filter(([source]) => !entries[bySource.get(source)[0]].trusted).map(([source, keys]) => ({ source, keys, sha256: entries[keys[0]].sha256 })).concat(untrustedExtending)

  for (const i of ignored) if (!i.reason.startsWith('first-party key (')) logs.push(`Stack manifest ignored: ${i.source} — ${i.reason}`)
  if (stale.length) {
    const sources = stale.map((s) => s.source).join(', ')
    const fixes = ['file', 'plugin'].flatMap((kind) => [...new Set(stale.filter((s) => s.kind === kind).map((s) => s.fix))])
    logs.push(`First-party stack manifests differ from this core (${sources}). Fix: ${fixes.join('; ')}.`)
  }

  const overlayKeys = Object.keys(entries).sort()
  const keys = [...FIRST_PARTY_KEYS.filter((k) => k !== 'other'), ...overlayKeys, 'other']
  return { present, added, ignored, rejected, entries, keys, untrusted, logs, storeUnreadable: trust.unreadable, declinedKeys, unnamedRejections, extends: extendsMap }
}

/**
 * A first-party stack as a manifest entry, rebuilt from the registry blocks manifestRows projected. An
 * extending overlay overrides some of its fields and inherits the rest.
 * @param {string} key a first-party stack key
 * @returns {object} the entry
 */
export function firstPartyEntry(key) {
  const row = STACKS[key]
  const traits = hasOwn(STACK_TRAITS, key) ? STACK_TRAITS[key] : {}
  const extras = hasOwn(STACK_EXTRAS, key) ? STACK_EXTRAS[key] : {}
  const meta = extras.gates || {}
  const skip = traits.scaffoldSkipGates || []
  const entry = {
    role: row.role,
    detect: row.detect,
    agent: hasOwn(AGENT_PLUGIN, row.agent) ? { name: row.agent, plugin: AGENT_PLUGIN[row.agent] } : { name: row.agent },
    conventions: row.conventions,
    gates: row.gates.map((g) => ({ ...g, ...(meta[g.name] || {}), ...(skip.includes(g.name) ? { skipWhenScaffolded: true } : {}) })),
    debugPatterns: row.debugPatterns,
    acceptance: row.acceptance,
  }
  if (row.devUrl !== undefined) entry.devUrl = row.devUrl
  if (row.visual !== undefined) entry.visual = row.visual
  if (traits.buildGateGuard !== undefined) entry.buildGateGuard = traits.buildGateGuard
  if (traits.execWrapper !== undefined) entry.execWrapper = traits.execWrapper
  const contractSync = {}
  if (traits.routeListCommand !== undefined) contractSync.routeListCommand = traits.routeListCommand
  if (traits.contractTemplate !== undefined) contractSync.template = traits.contractTemplate
  if (traits.contractConsumer === true) contractSync.consumer = true
  if (Object.keys(contractSync).length) entry.contractSync = contractSync
  for (const f of MANIFEST_EXTRA_FIELDS) if (extras[f] !== undefined) entry[f] = extras[f]
  return entry
}

// Optional manifest blocks copied unchanged into STACK_EXTRAS.
export const MANIFEST_EXTRA_FIELDS = ['skills', 'scaffold', 'ci', 'e2e', 'e2eBackend', 'migrations', 'audit', 'markers', 'packages', 'packageManagers', 'sourceDirs', 'gateTemplates']

/**
 * The one projection of a manifest entry onto the registry: its STACKS row plus the trait and extra
 * blocks that sit beside it. gen-stacks renders the first-party registry through this function and
 * installOverlay applies it to overlay entries, so a schema field reaches both or neither.
 * @param {object} entry a validated manifest entry
 * @returns {{ row: object, traits: object, extras: object }} traits/extras are {} when the entry has none
 */
export function manifestRows(entry) {
  const row = {
    role: entry.role,
    detect: entry.detect,
    agent: entry.agent.name,
    conventions: entry.conventions,
    gates: entry.gates.map((g) => ({ name: g.name, command: g.command })),
    debugPatterns: entry.debugPatterns,
  }
  if (entry.devUrl !== undefined) row.devUrl = entry.devUrl
  if (entry.visual !== undefined) row.visual = entry.visual
  row.acceptance = entry.acceptance
  const traits = {}
  if (entry.buildGateGuard !== undefined) traits.buildGateGuard = entry.buildGateGuard
  if (entry.execWrapper !== undefined) traits.execWrapper = entry.execWrapper
  const cs = entry.contractSync || {}
  if (cs.routeListCommand !== undefined) traits.routeListCommand = cs.routeListCommand
  if (cs.template !== undefined) traits.contractTemplate = cs.template
  if (cs.consumer === true) traits.contractConsumer = true
  const skip = entry.gates.filter((g) => g.skipWhenScaffolded === true).map((g) => g.name)
  if (skip.length) traits.scaffoldSkipGates = skip
  const extras = {}
  const gates = {}
  for (const g of entry.gates) {
    const meta = {}
    if (g.kind !== undefined) meta.kind = g.kind
    if (g.unless !== undefined) meta.unless = g.unless
    if (g.requires !== undefined) meta.requires = g.requires
    if (g.lintFix !== undefined) meta.lintFix = g.lintFix
    if (g.scriptFallback !== undefined) meta.scriptFallback = g.scriptFallback
    if (Object.keys(meta).length) gates[g.name] = meta
  }
  if (Object.keys(gates).length) extras.gates = gates
  for (const f of MANIFEST_EXTRA_FIELDS) if (entry[f] !== undefined) extras[f] = entry[f]
  return { row, traits, extras }
}

// Specialist agents of the effective registry: name -> { plugin, stacks, source }. An untrusted overlay
// contributes none (OD-17a).
export function buildAgentInfo(overlay) {
  const info = {}
  for (const key of STACK_KEYS) {
    const name = STACKS[key].agent
    if (name === 'general-purpose' || (hasOwn(overlay, key) && !overlay[key].trusted)) continue
    if (!hasOwn(info, name)) {
      const own = hasOwn(overlay, key) ? overlay[key] : null
      info[name] = { plugin: hasOwn(AGENT_PLUGIN, name) ? AGENT_PLUGIN[name] : (own && own.plugin) || null, stacks: [], source: own ? own.source : null }
    }
    info[name].stacks.push(key)
  }
  return info
}

/**
 * Makes a mergeOverlay result the effective registry: STACKS, STACK_KEYS, STACK_AGENT, AGENT_INFO and
 * the trust of each overlay key. Everything stackCatalog, debugScanFor and gate planning read follows.
 */
export function installOverlay(merged) {
  const overlay = {}
  for (const [key, e] of Object.entries(merged.entries)) {
    const { row, traits, extras } = manifestRows(e.entry)
    STACKS[key] = row
    if (Object.keys(traits).length) STACK_TRAITS[key] = traits
    if (Object.keys(extras).length) STACK_EXTRAS[key] = extras
    overlay[key] = { source: e.source, plugin: e.entry.agent.plugin || null, trusted: e.trusted, sha256: e.sha256 }
    if (e.extends) overlay[key].declared = e.declared
  }
  EXTENDS = merged.extends || {}
  STACK_KEYS = merged.keys
  // An untrusted overlay's specialist name is never used: its steps run as the default agent (OD-17a).
  STACK_AGENT = Object.fromEntries(STACK_KEYS.map((k) => [k, hasOwn(overlay, k) && !overlay[k].trusted ? 'general-purpose' : STACKS[k].agent]))
  AGENT_INFO = buildAgentInfo(overlay)
  OVERLAY_META = overlay
  DECLINED_KEYS = merged.declinedKeys || {}
  DECLINED_UNNAMED = merged.unnamedRejections || []
  MANIFESTS_DECLINED = !!((merged.rejected || []).length || (merged.ignored || []).length || (merged.untrusted || []).length)
}

// --- Detect plumbing ---------------------------------------------------------

// Schema fragments every workflow spreads into its Detect result schema.
export const DETECT_EXTRA_SCHEMA = {
  stackManifests: {
    type: 'array',
    items: { type: 'object', required: ['source'], properties: { source: { type: 'string' }, raw: { type: 'string' }, sha256: { type: 'string' } } },
  },
  // Absent and unreadable stores are both null (or omitted); unreadable also adds a discovery error.
  trustStore: { type: ['string', 'null'] },
  discovery: {
    type: 'object',
    properties: {
      mode: { type: 'string', enum: DISCOVERY_MODES },
      method: { type: 'string', enum: DISCOVERY_METHODS },
      errors: { type: 'array', items: { type: 'string' } },
    },
  },
}
// Per repo: the gates whose `unless` globs matched a file or directory in that repo.
export const REPO_UNLESS_SCHEMA = {
  type: 'array',
  items: { type: 'object', required: ['gate', 'glob'], properties: { gate: { type: 'string' }, glob: { type: 'string' } } },
}
export const GATE_NAMES_SCHEMA = { type: 'array', items: { type: 'string' } }
// Per repo: the unmet entries of each gate whose requires list is unmet, each entry as the manifest writes it.
export const MISSING_REQUIRES_SCHEMA = {
  type: 'array',
  items: {
    type: 'object',
    required: ['gate', 'entries'],
    properties: { gate: { type: 'string' }, entries: { type: 'array', items: { anyOf: [{ type: 'string' }, { type: 'array', items: { type: 'string' } }] } } },
  },
}
export const EXEC_WRAPPER_FACT_SCHEMA = { type: 'object', required: ['present'], properties: { present: { type: 'boolean' }, running: { type: 'boolean' }, dir: { type: 'string' } } }
/**
 * The per-repo answers the Detect prompt asks for (stackDiscoveryPrompt), spread into the repo item of
 * every workflow's Detect schema. A structured-output agent only fills declared properties, so a field
 * the prompt asks for and this block omits never reaches cleanRepoFields.
 */
export const REPO_DETECT_SCHEMA = {
  // Gates of this repo's stack whose `unless` globs matched a file or directory here.
  unlessMatched: REPO_UNLESS_SCHEMA,
  // Exec wrapper of the stack manifest: present = its marker file exists here, running = its running check succeeded,
  // dir = this repo's path relative to the marker's directory, for a wrapper with workdir.
  execWrapper: EXEC_WRAPPER_FACT_SCHEMA,
  // Hostnames of the URLs at the manifest's devUrlFields in the running check's output, when that check passed.
  reportedDevHosts: GATE_NAMES_SCHEMA,
  // Gates whose `requires` file is absent in this repo.
  missingTools: GATE_NAMES_SCHEMA,
  // For each such gate with a requires list: the entries that are unmet.
  missingRequires: MISSING_REQUIRES_SCHEMA,
  // Per trusted extending manifest (keyed by its name): the facts above answered for that manifest's own fields.
  overlayFacts: {
    type: 'object',
    additionalProperties: { type: 'object', properties: { execWrapper: EXEC_WRAPPER_FACT_SCHEMA, reportedDevHosts: GATE_NAMES_SCHEMA, missingTools: GATE_NAMES_SCHEMA, missingRequires: MISSING_REQUIRES_SCHEMA, unlessMatched: REPO_UNLESS_SCHEMA } },
  },
  // Gates whose project script contains the `lintFix` flag.
  mutatingGates: GATE_NAMES_SCHEMA,
  // Gates whose project script contains the `scriptFallback` text.
  legacyScriptGates: GATE_NAMES_SCHEMA,
  // The lowest major each `scriptFallback` dependency's declared range admits; a dependency left out is unknown.
  dependencyMajors: {
    type: 'array',
    items: { type: 'object', required: ['dependency', 'major'], properties: { dependency: { type: 'string' }, major: { type: 'integer' } } },
  },
}

// Prints "<sha256> <file>" for each file: the canonical manifest hash (canonicalManifest + sha256), with node:crypto.
export const MANIFEST_HASH_COMMAND = `node -e 'const c=require("crypto"),f=require("fs");const j=(v)=>Array.isArray(v)?"["+v.map(j).join(",")+"]":v!==null&&typeof v=="object"?"{"+Object.keys(v).sort().map((k)=>JSON.stringify(k)+":"+j(v[k])).join(",")+"}":JSON.stringify(v);const s=(e)=>{if(e===null||typeof e!="object"||Array.isArray(e))return e;const{$schema,...r}=e;return r};for(const p of process.argv.slice(1)){const m=JSON.parse(f.readFileSync(p,"utf8"));console.log(c.createHash("sha256").update(j(Array.isArray(m)?m.map(s):s(m))).digest("hex"),p)}'`

// First-party manifest locations and the hash a copy that matches this core has, for the Detect prompt.
export function firstPartyHashLine() {
  return Object.keys(FIRST_PARTY_FILES)
    .filter((dir) => hasOwn(FIRST_PARTY_FILE_HASHES, dir))
    .map((dir) => `${dir} (${HOST_STACKS_DIR}/${dir}.json, ${HOST_USER_STACKS_DIR}/${dir}.json, plugin sdd-kit-${dir}): ${FIRST_PARTY_FILE_HASHES[dir]}`)
    .join('; ')
}

// Appended to every Detect prompt; the discovery recipe itself lives in the code-explorer agent.
// First-party copies come back as a hash, not their text: their content is inlined here already, and
// echoing it would cost thousands of output tokens on every run.
export function stackDiscoveryPrompt() {
  const firstParty = firstPartyHashLine()
  const hashRule = firstParty
    ? ` For a first-party location inside the project, hash the file first with \`${MANIFEST_HASH_COMMAND} <file>\`; when the hash equals the one listed for that add-on, return {source, sha256} and no raw. Expected hashes: ${firstParty}. A first-party location outside the project, or one whose hash differs or cannot be computed, returns raw like any other manifest.`
    : ''
  return `STACK MANIFESTS — follow your stack discovery recipe and also return: stackManifests (one item per manifest you found: source as project:${HOST_STACKS_DIR}/<file>, user:${HOST_USER_STACKS_DIR}/<file> or plugin:<name>@<marketplace> (plugin:<name>@inline for a --plugin-dir plugin), raw = the file text, unmodified.${hashRule}), trustStore (the verbatim text of ${HOST_TRUST_STORE_DIR}/trusted-stacks.json, where <home> is the home directory your recipe reads from the OS user database, never $HOME or CLAUDE_CONFIG_DIR; null or omitted when the file is absent; null or omitted plus "trustStore unreadable" in discovery.errors when <home> cannot be resolved or the Read is refused or fails), and discovery {mode, method, errors}. Outside the project use only the Read and Glob tools, on literal absolute paths under the <config> directory and the ${HOST_TRUST_STORE_DIR} directory your recipe resolves: never cat, ls or find there, and no Bash command with a variable in braces.${workdirOutsideRule()} A refused read goes into discovery.errors ("trustStore unreadable", "user stacks unreadable", "plugin list unreadable") and is never treated as trusted. A repo that matches no catalog stack but matches a manifest's detect text takes that manifest's name as stack. For each repo and each gate of its stack that lists unless globs, add {gate, glob} to unlessMatched for every glob that matches a file or directory in that repo (${UNLESS_GLOB_RULE}). TRUST — run a discovered manifest's own commands (its running check, and test -e through its exec wrapper) only when its canonical sha256, computed with \`${MANIFEST_HASH_COMMAND} <file>\`, appears in the trustStore text you read; for any other manifest report only host-side reads (marker presence and unless matches). OVERLAY FACTS — for each such trusted manifest that declares extends: <key>, add to every repo of stack <key> an overlayFacts.<manifest name> object {execWrapper, reportedDevHosts, missingTools, unlessMatched}, answered for that manifest's own fields.${execWrapperDetectLine()}${gateGuardDetectLine()}

${REPO_PATH_RULE}`
}

// Local development hosts only: localhost, the loopback addresses, and *.localhost, *.test and every first-party
// devUrlHosts suffix. A suffix needs at least one label before it; labels may use any case, suffixes are lower case.
export const DEV_URL_SUFFIXES = ['localhost', 'test', ...DEV_URL_HOSTS]
// Port, plain path and a query string. The query set holds no space, quote, backtick, $, ;, &, <, > or #, so a
// dev URL cannot break out of the quoted text of a prompt or chain a second command when an agent pastes it
// into a shell line.
export const DEV_URL_TAIL = '(?::\\d{1,5})?(?:\\/[A-Za-z0-9._~/-]*)?(?:\\?[A-Za-z0-9._~=%/-]*)?$'
export const DEV_URL_PATTERN = new RegExp(
  `^https?:\\/\\/(?:localhost|127\\.0\\.0\\.1|\\[::1\\]|(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+(?:${DEV_URL_SUFFIXES.map(escapeRegex).join('|')}))${DEV_URL_TAIL}`
)
// A hostname a repo's running check reported through its manifest's devUrlFields: two or more DNS labels.
export const REPORTED_HOST_PATTERN = /^(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/
// A dev URL on such a host; group 1 is the hostname, matched against the repo's reported hosts.
export const REPORTED_HOST_URL_PATTERN = new RegExp(`^https?:\\/\\/(${REPORTED_HOST_PATTERN.source.slice(1, -1)})${DEV_URL_TAIL}`)
// Private and reserved top-level names (RFC 2606, RFC 6761, RFC 6762 appendix G, RFC 8375, ICANN .internal).
// A reported host widens the dev-URL rule only when it ends in one of them or in a dev URL suffix; any other host,
// such as an extra FQDN on a public or country-code TLD (staging.example.com, shop.co.uk) or an IP address, is dropped.
export const PRIVATE_TLDS = ['internal', 'local', 'lan', 'home.arpa', 'localhost', 'test', 'example', 'invalid', 'intranet', 'private', 'corp', 'home']
// The same host set as prose, for prompts, logs and Fix text.
export const DEV_URL_HOST_TEXT = `localhost, 127.0.0.1, [::1] or a ${DEV_URL_SUFFIXES.map((h) => `*.${h}`).join(', ').replace(/, ([^,]*)$/, ' or $1')} host`
// How Detect reports repo paths and dev URLs so that resolveDetect keeps them (isRepoPath, isDevUrl).
export const REPO_PATH_RULE = `REPO PATHS — report each repo's path relative to the current directory ("." for the current directory itself), using only letters, digits, ".", "_", "/" and "-", with no ".." segment and no leading "-". A repo outside the current directory is reported only when the caller hinted its root, and then with that hint verbatim. Any other path drops the repo. devUrl must be an http(s) URL on ${DEV_URL_HOST_TEXT}, or on a host in that repo's reportedDevHosts (optional port, plain path and query string); any other devUrl is dropped.`

/**
 * Runs the Detect agent call, turning a throw into a failure message instead of ending the workflow.
 * @param {string} prompt the Detect prompt
 * @param {object} opts options for runAgent
 * @returns {Promise<{ project: object|null, failure: string|null }>}
 */
export async function detectStacks(prompt, opts) {
  try {
    return { project: await runAgent(prompt, opts), failure: null }
  } catch (e) {
    return { project: null, failure: (e && e.message) || String(e) }
  }
}

/**
 * Turns Detect's raw result into the repos a workflow runs on and merges the stack overlay.
 * Never re-runs Detect: a failure, a null result or zero repos all end in the single fallback repo.
 * @param {object|null} project Detect's result, null when it failed
 * @param {{ failure?: string, listKey?: string, fallback?: object }} [opts] failure: message when Detect threw; listKey: the repo list property (default "repos"); fallback: the repo used when none were detected
 * @returns {{ list: object[], stackOverlay: object, untrusted: object[] }}
 */
export function resolveDetect(project, opts) {
  const o = opts || {}
  const listKey = o.listKey || 'repos'
  const data = project && typeof project === 'object' ? project : null
  const failure = o.failure || (data ? null : 'Detect returned no result')
  const discovery = { mode: 'unknown', method: 'none', errors: [] }
  const found = data && data.discovery && typeof data.discovery === 'object' ? data.discovery : null
  if (found) {
    if (DISCOVERY_MODES.includes(found.mode)) discovery.mode = found.mode
    if (DISCOVERY_METHODS.includes(found.method)) discovery.method = found.method
    if (Array.isArray(found.errors)) discovery.errors = safeTexts(found.errors, 'Detect discovery errors')
  }
  if (failure) {
    discovery.mode = 'none'
    discovery.method = 'none'
    discovery.errors = [`Detect failed: ${failure}`]
  }
  discoveryMode = discovery.mode
  const roots = callerRoots(o.roots)
  let list = (data && Array.isArray(data[listKey]) ? data[listKey] : []).filter((r) => {
    if (r && typeof r === 'object' && isRepoPath(r.path, roots)) return true
    const shown = r && typeof r === 'object' && typeof r.path === 'string' ? JSON.stringify(r.path.slice(0, 80)) : '(none)'
    log(`Repo dropped: path ${shown} is not a relative path inside the workspace. Fix: run from a directory that contains every repo, or pass the repo roots in args.repos.`)
    return false
  })
  if (!list.length) {
    if (!failure) discovery.errors.push('Detect returned no repos')
    list = [o.fallback || { role: 'fullstack', path: '.', stack: 'other', gateCommands: [] }]
  }
  const manifests = data && Array.isArray(data.stackManifests) ? data.stackManifests : []
  // A store Detect calls unreadable approves nothing, whatever text came back with it. The store lives in the OS
  // home directory, not the config directory, so a config directory inside the project does not affect it.
  const storeRefused = discovery.errors.includes('trustStore unreadable')
  const merged = mergeOverlay(manifests, !storeRefused && data && typeof data.trustStore === 'string' ? data.trustStore : null)
  if (merged.storeUnreadable && !discovery.errors.includes('trustStore unreadable')) discovery.errors.push('trustStore unreadable')
  installOverlay(merged)

  const stackOverlay = {
    discovery: { mode: discovery.mode, method: discovery.method, count: manifests.length, errors: discovery.errors },
    present: merged.present,
    added: merged.added,
    ignored: merged.ignored,
    rejected: merged.rejected,
  }
  log(`Stacks: discovery ${discovery.method}, ${manifests.length} manifest(s), ${discovery.errors.length} error(s); added: ${merged.added.map((a) => a.key).join(', ') || 'none'}; ignored: ${merged.ignored.length}; rejected: ${merged.rejected.length}`)
  merged.logs.forEach((line) => log(line))
  merged.untrusted.filter((u) => !u.extends).forEach((u) => log(`Stack manifest untrusted: ${u.source} (${u.keys.join(', ')}) — its gates will not run, and its steps run as the default agent with no stack skills (its specialist agent and skills are not used). Fix: run /stack-trust.`))
  return { list: list.map((r) => resolveRepo(r)), stackOverlay, untrusted: merged.untrusted }
}

// --- Detect values: everything a prompt or a command quotes passes a strict pattern -----
// Detect and scaffold agents read repository content, so every value they report is checked before a
// prompt or command quotes it. An invalid value is dropped and logged, never quoted.

export const REPO_ROLES = ['backend', 'frontend', 'fullstack', 'mobile']
export const REPO_PATH_PATTERN = /^[A-Za-z0-9._/-]{1,200}$/
// Prose Detect reports (conventions, warnings, blockers): words and plain punctuation, no quotes, shell
// operators, substitutions or redirections.
export const SAFE_TEXT_PATTERN = /^[\p{L}\p{N} .,:()/_+*@#%=–—-]{1,200}$/u
export const MAX_TEXT_ITEMS = 20
export const NOT_RUN_NO_GATE = 'not run (no allowlisted gate'

/**
 * Whether a repo path Detect reported may be quoted into a prompt or command: relative, inside the
 * workspace (no ".." segment), [A-Za-z0-9._/-] only and no leading "-"; or exactly a repo root the caller
 * passed in args.repos, which defines the workspace for a polyrepo run.
 * @param {unknown} p the reported path
 * @param {Set<string>} [roots] caller repo roots (callerRoots)
 * @returns {boolean}
 * @example isRepoPath('web') // true
 * @example isRepoPath('web" && touch x') // false
 * @example isRepoPath('../web', callerRoots({ frontend: '../web' })) // true
 */
export function isRepoPath(p, roots) {
  if (typeof p !== 'string' || !REPO_PATH_PATTERN.test(p) || p.startsWith('-')) return false
  if (roots && roots.has(p)) return true
  return !p.startsWith('/') && !p.split('/').includes('..')
}

/**
 * The tracker key a workflow may put into a branch name, a folder or file name, or shell text: an uppercase
 * Jira-style key (PROJ-123) of at most 64 characters, so it holds no shell metacharacter or path separator
 * and stays a valid ref name. Anything else gives ''.
 * @param {unknown} value the ticket the caller passed or the run read
 * @returns {string} the key, or '' when it is not a safe key
 * @example ticketKey('PROJ-123') // 'PROJ-123'
 * @example ticketKey('proj-123') // ''
 * @example ticketKey('PROJ-1; rm -rf ~') // ''
 */
export function ticketKey(value) {
  return typeof value === 'string' && value.length <= 64 && /^[A-Z][A-Z0-9_]+-\d+$/.test(value) ? value : ''
}

// The repo roots a caller passed (args.repos as an object or array of paths), limited to the path characters.
export function callerRoots(hints) {
  const values = (Array.isArray(hints) ? hints : hints && typeof hints === 'object' ? Object.values(hints) : []).map((v) => (v && typeof v === 'object' ? v.path : v))
  return new Set(values.filter((v) => typeof v === 'string' && REPO_PATH_PATTERN.test(v) && !v.startsWith('-')))
}

/**
 * Whether a dev server URL may be quoted: http(s) on a local development host, or on exactly one of the hosts the
 * repo's own running check reported (reportedHostsFor), with an optional port, plain path and query string.
 * @param {unknown} url the URL
 * @param {string[]} [repoHosts] the reportedDevHosts of the repo the URL is for, lower case
 * @returns {boolean}
 * @example isDevUrl('https://shop.test/user/login?destination=/node') // true
 * @example isDevUrl('https://shop.internal', ['shop.internal']) // true
 * @example isDevUrl('https://other.internal', ['shop.internal']) // false
 */
export function isDevUrl(url, repoHosts) {
  if (typeof url !== 'string' || url.length > 200) return false
  if (DEV_URL_PATTERN.test(url)) return true
  const m = Array.isArray(repoHosts) && repoHosts.length ? REPORTED_HOST_URL_PATTERN.exec(url) : null
  return !!m && repoHosts.includes(m[1].toLowerCase())
}

/**
 * The hosts a repo's running check reported through its manifest's execWrapper.requiresRunning.devUrlFields,
 * kept only when the manifest is first-party or trusted, declares the field, and the check passed. A host must
 * have two or more DNS labels and end in a PRIVATE_TLDS name or a dev URL suffix; the rest are dropped and logged.
 * @param {object} r the reported repo
 * @param {string} stack its resolved stack key
 * @param {boolean} declined whether the stack comes from a manifest this run does not use
 * @returns {string[]} lower-case hostnames, at most MAX_TEXT_ITEMS
 * @example reportedHostsFor({ path: '.', execWrapper: { present: true, running: true }, reportedDevHosts: ['Site.internal', 'staging.example.com'] }, 'acme', false) // ['site.internal'] when acme's running check declares devUrlFields
 */
export function reportedHostsFor(r, stack, declined) {
  const declared = devUrlFieldsOf(traitsFor(stack).execWrapper).length > 0
  const ran = r.execWrapper && typeof r.execWrapper === 'object' && r.execWrapper.present === true && r.execWrapper.running === true
  if (!Array.isArray(r.reportedDevHosts) || declined || isUntrustedStack(stack) || !declared || !ran) return []
  const where = r.path || '.'
  const hosts = []
  const publicHosts = []
  let invalid = 0
  const isPrivate = (h) => [...PRIVATE_TLDS, ...DEV_URL_SUFFIXES].some((tld) => h.endsWith(`.${tld}`))
  for (const h of r.reportedDevHosts) {
    if (typeof h !== 'string' || h.length > 253 || !REPORTED_HOST_PATTERN.test(h)) invalid++
    else if (!isPrivate(h.toLowerCase())) publicHosts.push(h)
    else if (!hosts.includes(h.toLowerCase())) hosts.push(h.toLowerCase())
  }
  if (publicHosts.length) log(`Reported dev hosts dropped for ${where}: ${publicHosts.slice(0, 5).join(', ')} are not on a private development TLD (${PRIVATE_TLDS.join(', ')}). Fix: open that site by a host on one of them or ${DEV_URL_HOST_TEXT}`)
  if (invalid) log(`Reported dev hosts dropped for ${where}: ${invalid} value(s) are not hostnames.`)
  if (hosts.length > MAX_TEXT_ITEMS) log(`Reported dev hosts for ${where}: ${hosts.length - MAX_TEXT_ITEMS} beyond the first ${MAX_TEXT_ITEMS} dropped.`)
  return hosts.slice(0, MAX_TEXT_ITEMS)
}

/**
 * The prose items of a Detect list that pass SAFE_TEXT_PATTERN, at most MAX_TEXT_ITEMS; the rest are logged.
 * @param {unknown} list reported strings
 * @param {string} label what the list is, for the log line
 * @returns {string[]}
 */
export function safeTexts(list, label) {
  if (!Array.isArray(list)) return []
  const kept = list.filter((t) => typeof t === 'string' && SAFE_TEXT_PATTERN.test(t)).slice(0, MAX_TEXT_ITEMS)
  if (kept.length < list.length) log(`${label}: ${list.length - kept.length} item(s) dropped (quotes, shell syntax or too long).`)
  return kept
}

/**
 * A package manager name a scaffold or Detect reported, kept only when the stack's first-party or trusted
 * manifest declares it in packageManagers.
 * @param {string} stack Stack key.
 * @param {unknown} name the reported name
 * @param {string} where repo path, for the log line
 * @returns {string} the name, or '' when it was dropped
 */
export function declaredPackageManager(stack, name, where) {
  if (name === undefined || name === null || name === '') return ''
  if (packageManagersFor(stack).some((p) => p.name === name)) return name
  log(`Package manager dropped for ${where}: ${JSON.stringify(String(name).slice(0, 40))} is not declared by the ${stack} manifest.`)
  return ''
}

// The reported gate names that the stack's manifest gives the field (requires, lintFix, scriptFallback).
export function declaredGateNames(stack, names, field) {
  const gates = extrasFor(stack).gates || {}
  return (Array.isArray(names) ? names : []).filter((n) => typeof n === 'string' && hasOwn(gates, n) && gates[n][field] !== undefined)
}

// The reported unmet requires entries, kept only for gates with a requires list and only for entries that list declares, in its order.
export function declaredMissingRequires(stack, reported) {
  const gates = extrasFor(stack).gates || {}
  const seen = new Set()
  const out = []
  for (const m of Array.isArray(reported) ? reported : []) {
    if (!m || typeof m.gate !== 'string' || !hasOwn(gates, m.gate) || !Array.isArray(gates[m.gate].requires) || seen.has(m.gate) || !Array.isArray(m.entries)) continue
    const entries = gates[m.gate].requires.filter((e) => m.entries.some((r) => sameRequiresEntry(e, r)))
    if (!entries.length) continue
    seen.add(m.gate)
    out.push({ gate: m.gate, entries })
  }
  return out
}

/**
 * The gates of the effective registry that declare a guard field, as "<stack> gate <name> (<detail>)".
 * @param {string} field requires, lintFix or scriptFallback
 * @param {(value: object) => string} detail renders the field's value
 * @returns {string[]}
 */
export function guardedGates(field, detail) {
  const out = []
  for (const k of Object.keys(STACK_EXTRAS)) {
    const gates = STACK_EXTRAS[k].gates || {}
    for (const name of Object.keys(gates)) if (gates[name][field] !== undefined) out.push(`${k} gate ${name} (${detail(gates[name][field])})`)
  }
  return out
}

// How Detect probes a requires path; the trust-store plan step probes the same way.
export const WRAPPER_PROBE_RULE = 'check it through the exec wrapper (the repo\'s execWrapper command, then test -e <path>) only when execWrapper.present is true and either the manifest declares no running check or execWrapper.running is true, otherwise with test -e <path> in the repo; a wrapper that is not running is never used'

// WRAPPER_PROBE_RULE, plus the workdir flag for a nested repo when a manifest declares workdir.
export function wrapperProbeRule() {
  if (!workdirStacks().length) return WRAPPER_PROBE_RULE
  return `${WRAPPER_PROBE_RULE}; for a wrapper with workdir and an execWrapper.dir other than ".", put the workdir flag and <root>/<dir> between the command and test -e`
}

// The BINARY CHECK sentence for the list form of requires; '' while no manifest uses it.
export function binaryCheckListRules() {
  const lists = Object.keys(STACK_EXTRAS).some((k) => Object.values(STACK_EXTRAS[k].gates || {}).some((g) => Array.isArray(g.requires)))
  return lists ? ' A requires list is unmet when any entry is unmet; an entry that is a list of paths is met when at least one of its paths exists. For a gate with an unmet requires list, also add {gate, entries} to missingRequires, where entries are its unmet entries exactly as the manifest writes them.' : ''
}

/**
 * The binary-check, lint-fix and script-fallback questions Detect answers per repo. The prompt is built
 * before the manifests Detect discovers are merged, so each question also covers the same field in a
 * discovered manifest; cleanRepoFields keeps only the gate names the merged, trusted registry declares it on.
 * @returns {string}
 */
export function gateGuardDetectLine() {
  const known = (list) => (list.length ? `${list.join('; ')}; a discovered manifest's gates declare their own` : `as a discovered manifest's gates declare it`)
  const rules = guardedGates('requires', requiresDetectText)
  const fixes = guardedGates('lintFix', (v) => `flag ${v.flag}`)
  const majors = guardedGates('scriptFallback', (v) => `${v.dependency} from ${v.manifest}, major ${v.minMajor} or later, script containing "${v.contains}"`)
  return [
    ` BINARY CHECK — for each repo and gate that declares requires (${known(rules)}), add the gate name to missingTools when that file does not exist in the repo; ${wrapperProbeRule()}.${binaryCheckListRules()}`,
    ` MUTATING LINT — for each repo and gate that declares a lintFix flag (${known(fixes)}), add the gate name to mutatingGates when the repo's script for that gate contains the flag.`,
    ` DEPENDENCY MAJOR — for each repo and gate that declares a scriptFallback (${known(majors)}), add {dependency, major} to dependencyMajors, where major is the lowest major version (an integer) that the version range declared for that dependency in the named manifest file of the repo admits; leave the dependency out when that range cannot be read. Add the gate name to legacyScriptGates when the repo's script for that gate contains the quoted text.`,
  ].join('')
}

// The reported dependency majors for dependencies a scriptFallback of the stack's manifest names, one per dependency.
export function declaredMajors(stack, majors) {
  const gates = extrasFor(stack).gates || {}
  const deps = new Set(Object.keys(gates).filter((n) => gates[n].scriptFallback !== undefined).map((n) => gates[n].scriptFallback.dependency))
  const seen = new Set()
  return (Array.isArray(majors) ? majors : []).filter((m) => {
    if (!m || typeof m.dependency !== 'string' || !deps.has(m.dependency) || seen.has(m.dependency) || !Number.isInteger(m.major) || m.major < 0) return false
    seen.add(m.dependency)
    return true
  }).map((m) => ({ dependency: m.dependency, major: m.major }))
}

// The unless matches whose gate and glob the stack's manifest declares, in the manifest's unless order, so a
// gate's skip text names the same glob whatever order Detect reported them in.
export function declaredUnless(stack, matched) {
  const gates = (hasOwn(STACK_EXTRAS, stack) && STACK_EXTRAS[stack].gates) || {}
  const rank = (m) => gates[m.gate].unless.indexOf(m.glob)
  return (Array.isArray(matched) ? matched : []).filter((m) => m && hasOwn(gates, m.gate) && (gates[m.gate].unless || []).includes(m.glob)).sort((a, b) => rank(a) - rank(b))
}

// How an unless glob matches, as Detect is told it; unlessGlobMatches implements it for the plan step.
export const UNLESS_GLOB_RULE = 'a glob is relative to the repo root; * and ? match within one path segment'

/**
 * Whether an unless glob matches a file or directory of a repo, by UNLESS_GLOB_RULE. The runtime reads no
 * files itself, so the caller lists directories.
 * @param {string} glob an unless entry, for example "lint.config.*" or "config/*.json"
 * @param {(dir: string) => string[]|null} entries the entry names of a repo-relative directory ('' is the root), null when it is not one
 * @returns {boolean}
 * @example unlessGlobMatches('lint.config.*', (dir) => (dir === '' ? ['lint.config.json'] : null)) // true
 */
export function unlessGlobMatches(glob, entries) {
  const parts = glob.split('/').filter((p) => p !== '' && p !== '.')
  const walk = (dir, i) => {
    const names = entries(dir)
    if (!names) return false
    const re = new RegExp(`^${parts[i].replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.')}$`)
    const hits = names.filter((n) => re.test(n))
    return i === parts.length - 1 ? hits.length > 0 : hits.some((n) => walk(dir ? `${dir}/${n}` : n, i + 1))
  }
  return parts.length > 0 && walk('', 0)
}

/**
 * The fields of a Detect repo that workflows use, each validated for the repo's resolved stack. Unknown
 * fields are dropped, so a prompt that quotes the repo quotes only checked values.
 * @param {object} r the reported repo
 * @param {string} stack its resolved stack key
 * @param {boolean} declined whether the stack comes from a manifest this run does not use
 * @returns {object}
 */
export function cleanRepoFields(r, stack, declined) {
  const where = r.path || '.'
  const out = { role: REPO_ROLES.includes(r.role) ? r.role : 'fullstack', path: r.path || '.' }
  if (r.role !== undefined && out.role !== r.role) log(`Repo role dropped for ${where}: ${JSON.stringify(String(r.role).slice(0, 40))} is not ${REPO_ROLES.join(', ')}.`)
  for (const flag of ['tracked', 'e2eConfig', 'empty', 'hasTrackedFiles']) if (typeof r[flag] === 'boolean') out[flag] = r[flag]
  const pm = declaredPackageManager(stack, r.packageManager, where)
  if (pm) out.packageManager = pm
  if (r.execWrapper && typeof r.execWrapper === 'object' && typeof r.execWrapper.present === 'boolean') {
    out.execWrapper = { present: r.execWrapper.present }
    if (typeof r.execWrapper.running === 'boolean') out.execWrapper.running = r.execWrapper.running
    // dir is the one Detect value that reaches a command line (the workdir argument), so it must be a plain relative path.
    const dir = r.execWrapper.dir
    if (dir !== undefined) {
      const declared = traitsFor(stack).execWrapper
      if (declared && declared.workdir && isRepoPath(dir)) out.execWrapper.dir = dir
      else {
        log(`execWrapper dir ${JSON.stringify(String(dir).slice(0, 40))} dropped for ${where}. Fix: report a plain relative dir, or declare execWrapper.workdir in the ${stack} manifest`)
        if (declared && declared.workdir) out.execWrapper.dirUnusable = true
      }
    }
  }
  const hosts = reportedHostsFor(r, stack, declined)
  if (hosts.length) out.reportedDevHosts = hosts
  if (isDevUrl(r.devUrl, hosts)) out.devUrl = r.devUrl
  else if (r.devUrl !== undefined && r.devUrl !== '') log(`devUrl dropped for ${where}: ${JSON.stringify(String(r.devUrl).slice(0, 80))} is not an http(s) URL on ${DEV_URL_HOST_TEXT}.`)
  const ownStack = !declined && !isUntrustedStack(stack)
  if (hasOwn(r, 'conventions')) out.conventions = ownStack ? safeTexts(r.conventions, `Conventions for ${where}`) : []
  if (hasOwn(r, 'warnings')) out.warnings = safeTexts(r.warnings, `Warnings for ${where}`)
  if (hasOwn(r, 'unlessMatched')) out.unlessMatched = declaredUnless(stack, r.unlessMatched)
  if (hasOwn(r, 'missingTools')) out.missingTools = declaredGateNames(stack, r.missingTools, 'requires')
  if (hasOwn(r, 'missingRequires')) out.missingRequires = declaredMissingRequires(stack, r.missingRequires)
  if (hasOwn(r, 'mutatingGates')) out.mutatingGates = declaredGateNames(stack, r.mutatingGates, 'lintFix')
  if (hasOwn(r, 'dependencyMajors')) out.dependencyMajors = declaredMajors(stack, r.dependencyMajors)
  if (hasOwn(r, 'legacyScriptGates')) out.legacyScriptGates = declaredGateNames(stack, r.legacyScriptGates, 'scriptFallback')
  return out
}

/**
 * Moves a repo of an extended first-party stack onto the trusted overlay that extends it. The overlay's
 * own Detect facts replace the repo's. A declared execWrapper with no reported wrapper fact counts as
 * present and not running, so its gates skip instead of running unwrapped; an inherited one keeps the
 * repo's first-party fact.
 * @param {object} r the repo as Detect reported it
 * @returns {object} the repo with the overlay key as its stack, or r itself
 */
export function applyExtends(r) {
  if (typeof r.stack !== 'string' || !hasOwn(EXTENDS, r.stack)) return r
  const key = EXTENDS[r.stack]
  const all = r.overlayFacts && typeof r.overlayFacts === 'object' ? r.overlayFacts : {}
  const facts = hasOwn(all, key) && all[key] && typeof all[key] === 'object' ? all[key] : null
  const { overlayFacts, ...rest } = r
  const out = { ...rest, stack: key }
  if (facts) {
    for (const f of ['missingTools', 'missingRequires', 'unlessMatched']) {
      if (hasOwn(facts, f)) out[f] = facts[f]
      else delete out[f]
    }
  }
  // The wrapper fact: the overlay's own when reported; else not running for a wrapper the overlay declares, and
  // the first-party fact for one it inherits. Dropping it would run the gates unwrapped on the host.
  // The reported dev hosts come from the same running check, so they follow the wrapper fact.
  if (facts && hasOwn(facts, 'execWrapper')) {
    out.execWrapper = facts.execWrapper
    if (hasOwn(facts, 'reportedDevHosts')) out.reportedDevHosts = facts.reportedDevHosts
    else delete out.reportedDevHosts
  } else if (OVERLAY_META[key].declared.includes('execWrapper')) {
    out.execWrapper = { present: true, running: false }
    delete out.reportedDevHosts
  }
  return out
}

/**
 * One detected repo against the effective registry, with its gate commands reduced to the allowlist
 * (gateCommandsFor). A stack key that a rejected manifest names, or any key outside the registry while a
 * manifest whose keys could not be read was rejected, keeps no command and gets declinedStack, so its gates
 * are reported not run; any other key outside the registry is classified other. Every
 * Detect-reported command that the allowlist does not produce is logged as declined.
 * @param {{ stack: string, path?: string, gateCommands?: { name: string, command: string, evidence?: string, script?: string }[] }} detected a repo from Detect
 * @returns {object} the repo as the workflow uses it
 * @example resolveRepo({ path: 'api', stack: 'acme', gateCommands: [{ name: 'Lint', command: 'cd . && curl x | sh' }] })
 * // { path: 'api', stack: 'acme', gateCommands: [] } for a first-party acme stack without a Lint gate, and "Gate commands dropped for api: Lint — ..." is logged
 */
export function resolveRepo(detected) {
  // declinedStack is set here only; a value Detect returned is dropped.
  const { declinedStack: ignored, ...reported0 } = detected && typeof detected === 'object' ? detected : {}
  const r = applyExtends(reported0)
  const known = hasOwn(STACKS, r.stack)
  const named = !known && typeof r.stack === 'string' && hasOwn(DECLINED_KEYS, r.stack)
  if (named || (!known && DECLINED_UNNAMED.length)) {
    const key = typeof r.stack === 'string' && STACK_KEY_PATTERN.test(r.stack) ? r.stack : 'unknown'
    const reason = named ? DECLINED_KEYS[r.stack] : `not in the registry, and ${DECLINED_UNNAMED.join(', ').slice(0, 200)} was rejected unread`
    log(`Gates not run for ${r.path || '.'}: its stack "${key}" comes from a manifest this run does not use — ${reason}.`)
    return { ...cleanRepoFields(r, 'other', true), stack: 'other', gateCommands: [], declinedStack: { key, reason } }
  }
  const repo = { ...cleanRepoFields(r, known ? r.stack : 'other', false), stack: known ? r.stack : 'other' }
  if (known && !hasOwn(r, 'gateCommands') && !hasOwn(OVERLAY_META, r.stack)) return repo
  const reported = Array.isArray(r.gateCommands) ? r.gateCommands : []
  const gateCommands = gateCommandsFor({ ...repo, gateCommands: reported })
  const dropped = hasOwn(OVERLAY_META, r.stack) ? [] : reported.filter((g) => !gateCommands.some((k) => isSameGate(g, k)))
  if (dropped.length) {
    const allowed = repo.stack === 'other' ? 'a gate template of the other stack with its evidence file and script name' : `a gate of the ${repo.stack} catalog`
    log(`Gate commands dropped for ${r.path || '.'}: ${dropped.map(gateLabel).join(', ')} — declined, not ${allowed}.`)
  }
  return { ...repo, gateCommands }
}

// One line for the "Stack overlay" part of a report.
export function stackOverlayLine(overlay, untrusted) {
  const names = (list) => list.map((x) => x.key).join(', ') || 'none'
  return `discovery ${overlay.discovery.method} (${overlay.discovery.mode}); added: ${overlay.added.map((x) => (x.extends ? `${x.key} extends ${x.extends}` : x.key)).join(', ') || 'none'}; ignored: ${overlay.ignored.length}; rejected: ${overlay.rejected.length}; untrusted: ${(untrusted || []).map((u) => u.keys.join(', ')).join(', ') || 'none'}`
}

/**
 * The untrusted manifests that hold the stack of a repo this run works on. Only these block a verdict;
 * any other untrusted manifest (an unused user overlay, an add-on for another stack) is reported for information.
 * @param {{ keys: string[] }[]} untrusted resolveDetect's untrusted list
 * @param {{ stack: string }[]} repos the detected repos or targets
 * @returns {object[]} the subset of `untrusted` that blocks
 */
export function blockingUntrusted(untrusted, repos) {
  const stacks = new Set((repos || []).map((r) => r.stack))
  return (untrusted || []).filter((u) => !u.extends && u.keys.some((k) => stacks.has(k)))
}

// "Next:" line that every untrusted-manifest recommendation ends with; '' when nothing is untrusted.
export const untrustedNext = (workflow, untrusted) => ((untrusted || []).length ? `Next: /stack-trust, then re-run ${workflow}.` : '')

// --- gates: the command allowlist, untrusted manifests and unless globs -----
// A gate command runs only when the registry produces it: (a) the inlined catalog of a first-party stack,
// (b) the approved manifest of a trusted overlay, or (c) for `other`, a gate template of the core other
// manifest rendered with a script name Detect found in the template's evidence file. Detect's text only
// selects among these; it never becomes a command itself.

// Script or target names a gate template accepts: no whitespace, quotes or shell syntax, no leading dash.
export const GATE_SCRIPT_PATTERN = /^[A-Za-z0-9][A-Za-z0-9:._-]{0,63}$/
export const CONTRACT_SYNC_COMMAND = 'node scripts/contract-sync.mjs'
export const CONTRACT_SYNC_SCRIPTS = ['contract-sync', 'contract:sync']

export const trimmed = (v) => (typeof v === 'string' ? v.trim() : '')
export const gateLabel = (g) => JSON.stringify(trimmed(g && g.name).slice(0, 60) || '?')
export const isSameGate = (reported, kept) => !!reported && (trimmed(reported.command) === kept.command || trimmed(reported.name).toLowerCase() === kept.name.toLowerCase())

// The gate templates of the core other manifest: { evidence, command } with {script} in the command.
export function gateTemplates() {
  return (hasOwn(STACK_EXTRAS, 'other') && STACK_EXTRAS.other.gateTemplates) || []
}

export const renderGateTemplate = (template, script) => template.command.split('{script}').join(script)

// The gate templates as one prompt fragment: "<evidence> → <command>; ...".
export function gateTemplatesLine() {
  return gateTemplates().map((t) => `${t.evidence} → ${t.command}`).join('; ') || '(none)'
}

// How an agent reports a stack's gate commands so that the allowlist keeps them, for a prompt.
export function gateReportRule(stack) {
  return stack === 'other'
    ? `each as {name, command, evidence, script} from these templates, any other command is dropped: ${gateTemplatesLine()}`
    : 'use the gate names and commands listed above verbatim, any other command is dropped'
}

/**
 * The gate an other repo runs for one Detect item, or null. The item must name a template's evidence file
 * and a script name that matches GATE_SCRIPT_PATTERN, and its command must equal that template rendered
 * with the script. The gate is named after the script and keeps its evidence, so planning it again keeps it.
 * @param {{ command?: string, evidence?: string, script?: string }} g a gate command Detect reported
 * @returns {{ name: string, command: string, evidence: string, script: string }|null}
 * @example templateGateCommand({ name: 'Lint', command: 'make lint', evidence: 'Makefile', script: 'lint' })
 * // { name: 'lint', command: 'make lint', evidence: 'Makefile', script: 'lint' }
 */
export function templateGateCommand(g) {
  if (!g || typeof g.script !== 'string' || !GATE_SCRIPT_PATTERN.test(g.script)) return null
  const evidence = trimmed(g.evidence).replace(/^\.\//, '')
  const command = trimmed(g.command)
  const template = gateTemplates().find((t) => t.evidence === evidence && renderGateTemplate(t, g.script) === command)
  return template ? { name: g.script, command, evidence, script: g.script } : null
}

/**
 * The catalog gates of a first-party stack that Detect found, in catalog order, with <pm>/<pmx> filled from
 * the package manager Detect recorded (the stack's default when it recorded none it declares). A Detect
 * item selects a catalog gate by its name or by the catalog command (raw or filled); its own text is not kept.
 */
export function catalogGateCommands(repo, reported) {
  const pms = packageManagersFor(repo.stack)
  const own = packageManagerFor(repo, false)
  const fill = own || pms[pms.length - 1] || null
  return STACKS[repo.stack].gates
    .filter((g) => {
      const forms = new Set([g.command.trim(), ...(own ? [own] : pms).map((pm) => fillPackageManager(g.command, pm).trim())])
      return reported.some((r) => r && (forms.has(trimmed(r.command)) || trimmed(r.name).toLowerCase() === g.name.toLowerCase()))
    })
    .map((g) => ({ name: g.name, command: fillPackageManager(g.command, fill) }))
}

/**
 * The gate commands a repo runs, from the allowlist only.
 * - A first-party stack: the catalog gates Detect found (catalogGateCommands).
 * - `other`: the gate templates Detect proved with an evidence file and script name (templateGateCommand).
 * - An overlay: none when untrusted; the approved manifest's gates when trusted, with <pm>/<pmx> filled from
 *   the package manager Detect recorded (the manifest's last, default, entry otherwise).
 * - A declined stack, or a stack outside the effective registry: none.
 * @param {{ stack: string, packageManager?: string, declinedStack?: object, gateCommands?: object[] }} repo
 * @returns {{ name: string, command: string, evidence?: string, script?: string }[]} evidence and script only for other
 */
export function gateCommandsFor(repo) {
  if (!hasOwn(STACKS, repo.stack) || repo.declinedStack) return []
  if (hasOwn(OVERLAY_META, repo.stack)) {
    if (isUntrustedStack(repo.stack)) return []
    const pm = packageManagerFor(repo)
    return STACKS[repo.stack].gates.map((g) => ({ name: g.name, command: fillPackageManager(g.command, pm) }))
  }
  const reported = (Array.isArray(repo.gateCommands) ? repo.gateCommands : []).filter((g) => g && typeof g === 'object')
  if (repo.stack !== 'other') return catalogGateCommands(repo, reported)
  const out = []
  for (const g of reported) {
    const gate = templateGateCommand(g)
    if (gate && !out.some((k) => k.command === gate.command)) out.push(gate)
  }
  return out
}

/**
 * The command that runs the contract-sync checker: the checker script itself, or a contract-sync script of
 * the repo's task runner rendered from a gate template. Anything else Detect reported is declined and logged.
 * @param {string|undefined} reported the command Detect reported
 * @returns {string} the command, or '' when it was declined
 */
export function contractSyncCommandFor(reported) {
  const command = trimmed(reported)
  if (!command) return CONTRACT_SYNC_COMMAND
  const allowed = [CONTRACT_SYNC_COMMAND, ...CONTRACT_SYNC_SCRIPTS.flatMap((script) => gateTemplates().map((t) => renderGateTemplate(t, script)))]
  if (allowed.includes(command)) return command
  log(`Contract-sync command declined: ${JSON.stringify(command.slice(0, 120))} is not ${CONTRACT_SYNC_COMMAND} or a contract-sync script. Fix: register the checker as a "contract-sync" script of the repo's task runner.`)
  return ''
}

// A gate failure the fix loop can act on: untrusted gates were never run, so there is nothing to fix.
export const isFixableGate = (g) => (g.status === 'fail' || g.status === 'unreachable') && g.details !== NOT_RUN_UNTRUSTED && !String(g.details || '').startsWith(NOT_RUN_DECLINED) && !String(g.details || '').startsWith(NOT_RUN_NO_GATE)

/**
 * Whether a repo with no allowlisted gate may fall back to the lint and test tooling it visibly has (AC-36):
 * only a first-party or other stack, and only when no manifest was rejected, ignored or untrusted in this run.
 * @param {{ stack: string, declinedStack?: object }} repo
 * @returns {boolean}
 */
export function toolingFallbackAllowed(repo) {
  return FIRST_PARTY_KEYS.includes(repo.stack) && !hasOwn(OVERLAY_META, repo.stack) && !repo.declinedStack && !MANIFESTS_DECLINED
}

/**
 * The gate-prompt line for a repo whose gate list is empty: the tooling fallback when it is allowed, else none.
 * @param {object} repo the repo the prompt is for
 * @param {string} [fallback] the fallback wording
 * @returns {string} one "- (...)" line
 */
export function noGatesLine(repo, fallback) {
  return toolingFallbackAllowed(repo) ? `- (${fallback || 'none detected — run any lint/test tooling that exists'})` : '- (no allowlisted gate — run no other lint/test tooling)'
}

/**
 * Splits a repo's gates into those to run, those decided without running, and the untrusted ones.
 * A repo whose stack comes from a declined manifest runs nothing: one unreachable gate names the reason.
 * @param {{ stack: string, declinedStack?: { key: string, reason: string }, gateCommands?: { name: string, command: string }[], unlessMatched?: { gate: string, glob: string }[] }} repo
 * @returns {{ untrusted: boolean, declined: boolean, run: object[], fixed: { name: string, status: string, details: string }[] }}
 */
export function gatePlanFor(repo) {
  if (repo.declinedStack) {
    const details = `${NOT_RUN_DECLINED}: stack "${repo.declinedStack.key}" — ${repo.declinedStack.reason})`
    return { untrusted: false, declined: true, run: [], fixed: [{ name: 'Quality gates', status: 'unreachable', details }] }
  }
  if (isUntrustedStack(repo.stack)) {
    // Gate names of an untrusted manifest are its text too, so they are reported by position only.
    return { untrusted: true, declined: false, run: [], fixed: STACKS[repo.stack].gates.map((g, i) => ({ name: `gate ${i + 1} (untrusted manifest)`, status: 'unreachable', details: NOT_RUN_UNTRUSTED })) }
  }
  const matched = repo.unlessMatched || []
  const wrapper = execWrapperFor(repo)
  const guards = extrasFor(repo.stack).gates || {}
  const run = []
  const fixed = []
  for (const g of gateCommandsFor(repo)) {
    const hit = matched.find((m) => m && m.gate === g.name)
    if (hit) fixed.push({ name: g.name, status: 'skip', details: `skipped — ${hit.glob} present` })
    else if (wrapper && wrapper.notRunning) fixed.push({ name: g.name, status: 'skip', details: `not run (${wrapper.command.split(' ')[0]} not running)` })
    else if (wrapper && wrapper.unplaced) fixed.push({ name: g.name, status: 'unreachable', details: `not run (${wrapper.command} cannot be pointed at the repo, whose path from the wrapper's marker directory holds characters a gate command does not carry). Fix: run the gate by hand from the repo's directory inside the container, or rename the directory to letters, digits, . _ - and /` })
    else if ((repo.missingTools || []).includes(g.name) && guards[g.name] && guards[g.name].requires !== undefined) {
      const unmet = (repo.missingRequires || []).find((m) => m && m.gate === g.name)
      fixed.push({ name: g.name, status: 'skip', details: requiresSkipText(guards[g.name].requires, unmet && unmet.entries) })
    }
    else {
      const fix = (repo.mutatingGates || []).includes(g.name) && guards[g.name] && guards[g.name].lintFix
      const legacy = (repo.legacyScriptGates || []).includes(g.name) && guards[g.name] && guards[g.name].scriptFallback
      // An unknown major takes the fallback: the script names a command the newer release removed, and the
      // fallback command works on the older releases as well.
      const known = legacy && (repo.dependencyMajors || []).find((m) => m.dependency === legacy.dependency)
      const outdated = legacy && (!known || known.major >= legacy.minMajor)
      const replacement = fix || (outdated && legacy)
      const command = replacement ? fillPackageManager(replacement.fallback, packageManagerFor(repo)) : g.command
      run.push(wrapper ? { ...g, command: `${wrapper.prefix} ${command}`, wrapped: true } : { ...g, command })
    }
  }
  if (!run.length && !fixed.length && !toolingFallbackAllowed(repo)) {
    const why = hasOwn(OVERLAY_META, repo.stack) ? `the ${repo.stack} manifest declares none` : 'a stack manifest was rejected, ignored or untrusted in this run'
    return { untrusted: false, declined: true, run: [], fixed: [{ name: 'Quality gates', status: 'unreachable', details: `${NOT_RUN_NO_GATE}; ${why})` }] }
  }
  return { untrusted: false, declined: false, run, fixed }
}

/**
 * Runs one repo's gates through an agent, resolving skipped and untrusted gates in the script.
 * @param {object} repo the detected repo (path, stack, gateCommands, unlessMatched)
 * @param {(repo: object) => string} instructionsFor builds the gate prompt for the gates that remain
 * @param {object} runOpts options for runAgent
 * @returns {Promise<{ repo: string, gates: object[], allPassed: boolean }|null>}
 */
export async function runRepoGates(repo, instructionsFor, runOpts) {
  const plan = gatePlanFor(repo)
  if (plan.untrusted || plan.declined) return { repo: repo.path, gates: plan.fixed, allPassed: false }
  if (!plan.run.length && plan.fixed.length) return { repo: repo.path, gates: plan.fixed, allPassed: false }
  const result = await runAgent(instructionsFor({ ...repo, gateCommands: plan.run }), runOpts)
  if (!result) return result
  const wrapper = execWrapperFor(repo)
  const wrapped = new Set(plan.run.filter((g) => g.wrapped).map((g) => g.name))
  const reported = (result.gates || []).map((g) => {
    if (!wrapped.has(g && g.name)) return g
    const details = mapContainerPaths(String(g.details || ''), wrapper)
    if (details.includes(wrapper.command)) return details === String(g.details || '') ? g : { ...g, details }
    return { ...g, details: `${details ? `${details} ` : ''}(via ${wrapper.command})` }
  })
  return plan.fixed.length || wrapped.size ? { ...result, gates: [...reported, ...plan.fixed] } : result
}
